export const SENTENCES = [
  {"id":"bcde5e2763","text":"Le jeune marin jeta un coup d’œil nonchalant sur ce commencement de manoeuvre, et, voyant que ses ordres allaient s’exécuter, il revint à son interlocuteur.","start":129,"end":135,"inf":"revenir","tense":"passe-simple","person":2,"work":0,"chapter":1},
  {"id":"2902e6a563","text":"Je crois que s’il eût été vide, et que j’en eusse été le maître, son intention eût été de l’acheter.","start":18,"end":21,"inf":"avoir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":1},
  {"id":"7fb1d9b449","text":"je ne sais pas même ce que je portais, et l’Empereur ne m’a fait que les questions qu’il eût faites au premier venu.","start":89,"end":92,"inf":"avoir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":1},
  {"id":"56954e38eb","text":"Mais dans l’antichambre il fut forcé d’invoquer l’autorité du roi.","start":27,"end":30,"inf":"être","tense":"passe-simple","person":2,"work":0,"chapter":10},
  {"id":"1fe55a63e8","text":"Si Bonaparte descendait à Naples, la coalition tout entière serait sur pied, avant seulement qu’il fût à Piombino.","start":99,"end":102,"inf":"être","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":10},
  {"id":"ae880f7f47","text":"Mais il craignit de se faire un ennemi mortel du ministre de la Police, bien qu’il sentît que celui-ci était irrévocablement perdu.","start":8,"end":16,"inf":"craindre","tense":"passe-simple","person":2,"work":0,"chapter":11},
  {"id":"87b380739e","text":"Il vint donc en aide au ministre au lieu de l’accabler.","start":3,"end":7,"inf":"venir","tense":"passe-simple","person":2,"work":0,"chapter":11},
  {"id":"c721708c0d","text":"Puis, craignant sans doute qu’il n’écoutât dans l’antichambre, il alla rouvrir derrière lui.","start":66,"end":70,"inf":"aller","tense":"passe-simple","person":2,"work":0,"chapter":12},
  {"id":"ea59311684","text":"Mais quand Napoléon fut de retour à Paris et que sa voix retentit de nouveau, impérieuse et puissante, Danglars eut peur.","start":20,"end":23,"inf":"être","tense":"passe-simple","person":2,"work":0,"chapter":13},
  {"id":"c62f62f2dc","text":"Il partit donc pour Madrid, et l’on n’entendit plus parler de lui.","start":3,"end":9,"inf":"partir","tense":"passe-simple","person":2,"work":0,"chapter":13},
  {"id":"02ab8f8b25","text":"Ils répondirent unanimement que la nourriture était détestable et qu’ils réclamaient leur liberté.","start":4,"end":15,"inf":"répondre","tense":"passe-simple","person":5,"work":0,"chapter":14},
  {"id":"875b9ac9de","text":"Et il fit signe au porte-clefs, qui ouvrit la porte.","start":6,"end":9,"inf":"faire","tense":"passe-simple","person":2,"work":0,"chapter":14},
  {"id":"eb6474ae3e","text":"Les soldats croisèrent aussitôt la baïonnette, car ils crurent que le prisonnier s’élançait vers l’inspecteur avec de mauvaises intentions.","start":55,"end":62,"inf":"croire","tense":"passe-simple","person":5,"work":0,"chapter":14},
  {"id":"f5e4b516b5","text":"Il commença par l’orgueil, qui est une suite de l’espoir et une conscience de l’innocence.","start":3,"end":11,"inf":"commencer","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"48bb0bd137","text":"Enfin il tomba du haut de son orgueil, il pria, non pas encore Dieu, mais les hommes.","start":9,"end":14,"inf":"tomber","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"73ab403d02","text":"Dantès pria donc qu’on voulût bien le tirer de son cachot pour le mettre dans un autre, fût-il plus noir et plus profond.","start":23,"end":29,"inf":"vouloir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":15},
  {"id":"8aae623066","text":"Il s’était habitué à parler à son nouveau geôlier, quoiqu’il fût encore, s’il était possible, plus muet que l’ancien.","start":61,"end":64,"inf":"être","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":15},
  {"id":"80932c8390","text":"Dès que cette pensée eut germé dans l’esprit du jeune homme, il devint plus doux, plus souriant.","start":64,"end":70,"inf":"devenir","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"31139a4851","text":"Tout à coup le soir, vers neuf heures il entendit un bruit sourd à la paroi du mur contre lequel il était couché.","start":41,"end":49,"inf":"entendre","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"22e360848a","text":"Heureusement, il crut que Dantès avait le délire.","start":17,"end":21,"inf":"croire","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"309cc827f1","text":"Bientôt, il sentit que le jour rentrait dans son cerveau.","start":12,"end":18,"inf":"sentir","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"43a65a6f5b","text":"Il put penser et fortifier sa pensée avec le raisonnement.","start":3,"end":6,"inf":"pouvoir","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"f2f0c4b921","text":"Il alla vers un angle de sa prison, détacha une pierre minée par l’humidité, et revint frapper le mur à l’endroit même où le retentissement était le plus sensible.","start":3,"end":7,"inf":"aller","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"35948f228c","text":"Toute la nuit il écouta et entendit le mineur inconnu qui continuait son oeuvre souterraine.","start":17,"end":23,"inf":"écouter","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"376ad479b7","text":"Il revint un instant après, recommanda plus d’adresse au prisonnier et sortit.","start":3,"end":9,"inf":"revenir","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"1174af36fe","text":"Puis il regarda autour de lui dans quoi il pouvait verser la soupe.","start":8,"end":15,"inf":"regarder","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"adf2bb60c9","text":"Cette fois, il mangea vivement la soupe et la viande que, selon l’habitude des prisons, on mettait avec la soupe.","start":15,"end":21,"inf":"manger","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"a7d7804e71","text":"Sans doute il regarda le visiteur importun d’un œil étrange, car celui-ci lui dit.","start":14,"end":21,"inf":"regarder","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"fc8ea44fe8","text":"Mais le lendemain, après la visite du matin et comme il venait d’écarter son lit de la muraille, il entendit frapper trois coups à intervalles égaux.","start":100,"end":108,"inf":"entendre","tense":"passe-simple","person":2,"work":0,"chapter":15},
  {"id":"2630e0f490","text":"Il voulut le trouver en défaut sur un point quelconque, il continua.","start":3,"end":9,"inf":"vouloir","tense":"passe-simple","person":2,"work":0,"chapter":16},
  {"id":"5ec7a67906","text":"Et il rentra dans le corridor souterrain où il disparut.","start":6,"end":12,"inf":"rentrer","tense":"passe-simple","person":2,"work":0,"chapter":16},
  {"id":"3b126e59a0","text":"Un instant, elles ont été altérées, lorsqu’il eut lu la lettre qui me compromettait.","start":46,"end":49,"inf":"avoir","tense":"passe-simple","person":2,"work":0,"chapter":17},
  {"id":"b24e68d2d4","text":"Il jeta un cri, chancela un instant comme un homme ivre.","start":3,"end":7,"inf":"jeter","tense":"passe-simple","person":2,"work":0,"chapter":17},
  {"id":"cd7afca4b9","text":"Puis, comme l’en avait prié Dantès, il parla d’autre chose.","start":39,"end":44,"inf":"parler","tense":"passe-simple","person":2,"work":0,"chapter":17},
  {"id":"fdb74ea3d7","text":"Avec ces deux langues, il comprit bientôt le mécanisme de toutes les autres, et, au bout de six mois, il commençait à parler l’espagnol, l’anglais et l’allemand.","start":26,"end":33,"inf":"comprendre","tense":"passe-simple","person":2,"work":0,"chapter":17},
  {"id":"0bb8a29f10","text":"Oui, s’il arrivait qu’on pût mettre sur la galerie une sentinelle aveugle et sourde.","start":25,"end":28,"inf":"pouvoir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":17},
  {"id":"60a3211a52","text":"Ses yeux, constamment restés ouverts et atones, reprirent leur regard, un faible soupir s’échappa de sa bouche, il fit un mouvement.","start":115,"end":118,"inf":"faire","tense":"passe-simple","person":2,"work":0,"chapter":17},
  {"id":"e65180a8c2","text":"Lorsque Dantès rentra le lendemain matin dans la chambre de son compagnon de captivité, il trouva Faria assis, le visage calme.","start":91,"end":97,"inf":"trouver","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"50587af873","text":"Et, prenant ce papier, dont la moitié manquait, consumée qu’elle avait été sans doute par quelque accident, il lut.","start":111,"end":114,"inf":"lire","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"2707219f08","text":"Il entra huit cent mille écus dans les coffres des spéculateurs.","start":3,"end":8,"inf":"entrer","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"69f95f81eb","text":"On chercha plus activement encore peut-être que n’avaient fait les augustes héritiers.","start":3,"end":10,"inf":"chercher","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"3dc9ca71d8","text":"il resta deux palais et une vigne derrière le Palatin.","start":3,"end":8,"inf":"rester","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"2a50a84366","text":"Il suivit ce conseil, et doubla ainsi son revenu.","start":3,"end":9,"inf":"suivre","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"eb3860b7bc","text":"tout fut inutile, je restai dans mon ignorance, et le comte de Spada dans sa misère.","start":21,"end":27,"inf":"rester","tense":"passe-simple","person":0,"work":0,"chapter":18},
  {"id":"d98bf7e7ae","text":"Je levai la tête, j’étais dans l’obscurité la plus profonde.","start":3,"end":8,"inf":"lever","tense":"passe-simple","person":0,"work":0,"chapter":18},
  {"id":"e97fc1c027","text":"Je cherchai, en tâtonnant, cette feuille inutile, je la trouvai, je la tordis, et, la présentant à la flamme mourante, je l’allumai.","start":3,"end":11,"inf":"chercher","tense":"passe-simple","person":0,"work":0,"chapter":18},
  {"id":"0e35875a35","text":"Et maintenant, dit-il, lorsqu’il eut vu que Dantès en était arrivé à la dernière ligne, rapprochez les deux fragments, et jugez vous-même.","start":33,"end":36,"inf":"avoir","tense":"passe-simple","person":2,"work":0,"chapter":18},
  {"id":"04e34ebca7","text":"Il ouvrit les yeux et essaya de percer les épaisseurs de l’obscurité.","start":3,"end":9,"inf":"ouvrir","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"078df10723","text":"Les yeux fixés, il attendit intrépidement le moment d’administrer le remède sauveur.","start":19,"end":27,"inf":"attendre","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"8974398785","text":"Il attendit dix minutes, un quart d’heure, une demi-heure, rien ne bougea.","start":3,"end":11,"inf":"attendre","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"1cf1dee279","text":"Alors il pensa qu’il était temps d’essayer la dernière épreuve.","start":9,"end":14,"inf":"penser","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"c13482b977","text":"Mais dès que le jour eut vaincu, il comprit qu’il était seul avec un cadavre.","start":36,"end":43,"inf":"comprendre","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"509c4e1f7e","text":"Cette fois, il commença sa visite par Dantès.","start":15,"end":23,"inf":"commencer","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"acd382121d","text":"Il rentra donc dans la galerie souterraine et arriva à temps pour entendre les exclamations du porte-clefs, qui appelait à l’aide.","start":3,"end":9,"inf":"rentrer","tense":"passe-simple","person":2,"work":0,"chapter":19},
  {"id":"0503913137","text":"Puis, prenant congé du vieux Dantès, il descendit à son tour et alla rejoindre Danglars, qui l’attendait au coin de la rue Senac.","start":40,"end":49,"inf":"descendre","tense":"passe-simple","person":2,"work":0,"chapter":2},
  {"id":"195fa7d81b","text":"il espérait que le poids ne serait pas trop grand pour qu’il pût le soulever.","start":61,"end":64,"inf":"pouvoir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":20},
  {"id":"64b973a688","text":"Enfin, avec un bruit épouvantable, il entra comme une flèche dans une eau glacée qui lui fit pousser un cri, étouffé à l’instant même par l’immersion.","start":38,"end":43,"inf":"entrer","tense":"passe-simple","person":2,"work":0,"chapter":20},
  {"id":"7236331332","text":"En même temps, il sentit une violente douleur au genou.","start":18,"end":24,"inf":"sentir","tense":"passe-simple","person":2,"work":0,"chapter":21},
  {"id":"e2473ffa15","text":"De quelque côté que l’attaquassent le vieux marin ou ses camarades, il tint bon et ne fit aucun aveu.","start":71,"end":75,"inf":"tenir","tense":"passe-simple","person":2,"work":0,"chapter":22},
  {"id":"9ee84e72d9","text":"Ce fut donc dans cette situation réciproque que l’on arriva à Livourne.","start":53,"end":59,"inf":"arriver","tense":"passe-simple","person":2,"work":0,"chapter":22},
  {"id":"da98b70484","text":"Ce n’était point encore la mode à cette époque-là que l’on portât la barbe et les cheveux si développés.","start":59,"end":65,"inf":"porter","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":22},
  {"id":"4733916ce2","text":"Tout le jour on courut des bordées, le soir des feux s’allumèrent sur la côte.","start":16,"end":22,"inf":"courir","tense":"passe-simple","person":2,"work":0,"chapter":22},
  {"id":"56ea6ab92c","text":"Il prit en conséquence le contre-pied et retourna sur ses pas.","start":3,"end":7,"inf":"prendre","tense":"passe-simple","person":2,"work":0,"chapter":23},
  {"id":"8ee9fcb113","text":"Il trouva Edmond étendu sanglant et presque sans connaissance.","start":3,"end":9,"inf":"trouver","tense":"passe-simple","person":2,"work":0,"chapter":23},
  {"id":"efd5a23261","text":"Alors il descendit d’une marche rapide, mais cependant pleine de prudence.","start":9,"end":18,"inf":"descendre","tense":"passe-simple","person":2,"work":0,"chapter":24},
  {"id":"a48042c529","text":"Dantès alla couper l’olivier le plus fort qu’il put trouver, le dégarnit de ses branches, l’introduisit dans le trou et en fit un levier.","start":48,"end":51,"inf":"pouvoir","tense":"passe-simple","person":2,"work":0,"chapter":24},
  {"id":"c7fa8f8c45","text":"Cette fois, il tomba à genoux, comprimant de ses deux mains convulsives son cœur bondissant, et murmurant une prière intelligible pour Dieu seul.","start":15,"end":20,"inf":"tomber","tense":"passe-simple","person":2,"work":0,"chapter":24},
  {"id":"ae42980c32","text":"Il craignit d’être surpris s’il restait dans la caverne, et sortit son fusil à la main.","start":3,"end":11,"inf":"craindre","tense":"passe-simple","person":2,"work":0,"chapter":24},
  {"id":"48c946ac47","text":"Puis à son tour, il écouta le récit des aventuriers.","start":20,"end":26,"inf":"écouter","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"641b95a0e2","text":"Le lendemain, il acheta une barque toute neuve qu’il donna à Jacopo, en ajoutant à ce don cent piastres afin qu’il pût engager un équipage.","start":17,"end":23,"inf":"acheter","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"64da4e8a7d","text":"Il donna la mesure de ces compartiments, qui furent exécutés le lendemain.","start":3,"end":8,"inf":"donner","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"15b08b2d67","text":"Et, au lieu d’aborder au port habituel, il jeta l’ancre dans la petite crique.","start":43,"end":47,"inf":"jeter","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"9bcfa5e3dd","text":"Deux hommes de la barque de Jacopo passèrent sur son yacht pour l’aider à la manoeuvre, et il donna l’ordre de mettre le cap sur Marseille.","start":94,"end":99,"inf":"donner","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"f9de31ea63","text":"Enfin, il arriva jusqu’à la maison qu’avait habitée son père.","start":10,"end":16,"inf":"arriver","tense":"passe-simple","person":2,"work":0,"chapter":25},
  {"id":"793ba14c32","text":"un an à peine après la disparition de son fils, il mourut, le pauvre vieillard !","start":51,"end":57,"inf":"mourir","tense":"passe-simple","person":2,"work":0,"chapter":26},
  {"id":"2c25f54a1a","text":"Si le petit était vivant et qu’il vînt à moi pour connaître une bon fois pour toutes ses amis et ses ennemis, je ne dis pas.","start":34,"end":38,"inf":"venir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":26},
  {"id":"e5b720d508","text":"Une nuit cependant que j’entendais ses sanglots, je n’y pus résister et je montai.","start":75,"end":81,"inf":"monter","tense":"passe-simple","person":0,"work":0,"chapter":27},
  {"id":"2f46fa35da","text":"Il demanda huit jours encore, on les lui accorda.","start":3,"end":10,"inf":"demander","tense":"passe-simple","person":2,"work":0,"chapter":27},
  {"id":"de125c1d52","text":"Elle le trouva si changé, que, comme la première fois, elle voulut le faire transporter chez elle.","start":60,"end":66,"inf":"vouloir","tense":"passe-simple","person":2,"work":0,"chapter":27},
  {"id":"f2462954c0","text":"Le lendemain, monsieur, le lendemain, vous vîtes bien qu’elle en avait.","start":43,"end":48,"inf":"voir","tense":"passe-simple","person":4,"work":0,"chapter":27},
  {"id":"078b5a553a","text":"Quand l’empereur rentra, il écrivit, pria, menaça, si bien qu’à la seconde Restauration il fut fort persécuté comme bonapartiste.","start":28,"end":35,"inf":"écrire","tense":"passe-simple","person":2,"work":0,"chapter":27},
  {"id":"6f3d37d7b7","text":"Quelque temps après, on apprit que le comte de Morcerf, c’était le nom qu’il portait, était entré au service d’Ali-Pacha avec le grade de général instructeur.","start":24,"end":30,"inf":"apprendre","tense":"passe-simple","person":2,"work":0,"chapter":27},
  {"id":"341205a1ed","text":"Quand il connut la mort du vieillard, il revint.","start":9,"end":15,"inf":"connaître","tense":"passe-simple","person":2,"work":0,"chapter":27},
  {"id":"e72e7875c0","text":"Heureusement, il porta à temps la main à son gosier.","start":17,"end":22,"inf":"porter","tense":"passe-simple","person":2,"work":0,"chapter":29},
  {"id":"a16136a0cd","text":"Et elle s’élança vers la porte, qu’elle ouvrit en s’écriant.","start":40,"end":46,"inf":"ouvrir","tense":"passe-simple","person":2,"work":0,"chapter":3},
  {"id":"98663611af","text":"Il vint même deux remboursements qu’avait prévus monsieur Morrel, et que Coclès paya avec la même ponctualité que les traites qui étaient personnelles à l’armateur.","start":3,"end":7,"inf":"venir","tense":"passe-simple","person":2,"work":0,"chapter":30},
  {"id":"79f33be0e0","text":"Julie se rappela la recommandation d’Emmanuel et voulut suivre son père lorsqu’il sortit.","start":82,"end":88,"inf":"sortir","tense":"passe-simple","person":2,"work":0,"chapter":30},
  {"id":"10f763d2a8","text":"Elle leva les yeux et poussa une exclamation de joie.","start":5,"end":9,"inf":"lever","tense":"passe-simple","person":2,"work":0,"chapter":30},
  {"id":"70e270e4ee","text":"On mit le cap sur l’île, et la barque commença de voguer dans sa direction.","start":3,"end":6,"inf":"mettre","tense":"passe-simple","person":2,"work":0,"chapter":31},
  {"id":"3b44e65ec1","text":"Une fois convaincu de ce point important, il porta les yeux autour de lui.","start":45,"end":50,"inf":"porter","tense":"passe-simple","person":2,"work":0,"chapter":31},
  {"id":"bde27da2c7","text":"D’ailleurs ce serait fâcheux qu’il mourût, Dantès.","start":35,"end":41,"inf":"mourir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":4},
  {"id":"6c8d1a75bd","text":"Le garçon prit le papier, l’encre et la plume, et les déposa sur la table du berceau.","start":10,"end":14,"inf":"prendre","tense":"passe-simple","person":2,"work":0,"chapter":4},
  {"id":"01e9b0e11f","text":"Et, le premier, je serais bien fâché qu’il arrivât quelque chose à Dantès, ce bon Dantès !","start":43,"end":50,"inf":"arriver","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":4},
  {"id":"98d2b0e941","text":"Pendant ce temps, Fernand rentra, se versa un verre d’eau qu’il but, et alla s’asseoir sur une chaise.","start":64,"end":67,"inf":"boire","tense":"passe-simple","person":2,"work":0,"chapter":5},
  {"id":"b3eff5cf3c","text":"À peine s’il mangea quelques bouchées de pain et but quelques gouttes d’eau.","start":13,"end":19,"inf":"manger","tense":"passe-simple","person":2,"work":0,"chapter":8},
  {"id":"e3555c5a23","text":"La porte se referma, et Dantès alla devant lui, les mains étendues jusqu’à ce qu’il sentît le mur.","start":84,"end":90,"inf":"sentir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":8},
  {"id":"6a48a86367","text":"elle ne vit pas plus l’obscurité qu’elle n’avait vu la lumière, et le jour revint sans qu’elle vît le jour.","start":95,"end":98,"inf":"voir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":9},
  {"id":"217e40b68a","text":"Mais tout fut inutile, et il perdit, sans aucun résultat, deux heures à cette recherche.","start":29,"end":35,"inf":"perdre","tense":"passe-simple","person":2,"work":0,"chapter":32},
  {"id":"473ea2dbc6","text":"Il partit donc, et le samedi soir il arriva à la place de la Douane par la malle-poste.","start":3,"end":9,"inf":"partir","tense":"passe-simple","person":2,"work":0,"chapter":32},
  {"id":"dc2f65c103","text":"Alors il envoya sa carte à maître Pastrini, et se fit réclamer d’Albert de Morcerf.","start":9,"end":15,"inf":"envoyer","tense":"passe-simple","person":2,"work":0,"chapter":32},
  {"id":"fd952a50a9","text":"Mon cher Albert, reprit Franz, votre réponse est sublime, et vaut le Qu’il mourût du vieux Corneille.","start":75,"end":81,"inf":"mourir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":33},
  {"id":"3bfecdbb5b","text":"Albert se versa un verre de lacryma Christi, qu’il but à petits coups, en grommelant des paroles inintelligibles.","start":51,"end":54,"inf":"boire","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"a688eee9a5","text":"Il acheta de la poudre et des balles, et tout lui devint un but.","start":3,"end":9,"inf":"acheter","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"cc960733ff","text":"On s’inquiéta d’eux d’abord puis bientôt on sut qu’ils étaient allés rejoindre la bande de Cucumetto.","start":44,"end":47,"inf":"savoir","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"e06eaa2de2","text":"Il demanda où ils étaient, les bandits répondirent par un grand éclat de rire.","start":3,"end":10,"inf":"demander","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"04b8efd8d4","text":"On mit tous les noms dans un chapeau, celui de Carlini comme ceux des autres, et le plus jeune de la bande tira de l’urne improvisée un bulletin.","start":3,"end":6,"inf":"mettre","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"dd9fca5f72","text":"Le vieillard ne prononça point une parole, seulement il devint pâle comme un spectre.","start":56,"end":62,"inf":"devenir","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"62ac08fa6d","text":"Il suivit des yeux les moindres mouvements de Teresa et de son cavalier.","start":3,"end":9,"inf":"suivre","tense":"passe-simple","person":2,"work":0,"chapter":33},
  {"id":"f5db459b0b","text":"En ce moment la comtesse aperçut Franz et lui fit de la main un signe gracieux, auquel il répondit par une respectueuse inclination de tête.","start":90,"end":98,"inf":"répondre","tense":"passe-simple","person":2,"work":0,"chapter":34},
  {"id":"a891d49f26","text":"Il sortit, détacha la tavoletta, et la présenta à Franz.","start":3,"end":9,"inf":"sortir","tense":"passe-simple","person":2,"work":0,"chapter":34},
  {"id":"f938262f0e","text":"Ils le lui dirent tout franchement, et il reçut leurs excuses en homme qui appréciait leur délicatesse.","start":42,"end":47,"inf":"recevoir","tense":"passe-simple","person":2,"work":0,"chapter":36},
  {"id":"d477481dc4","text":"Il promit donc à Albert qu’il se contenterait le lendemain de regarder le spectacle des fenêtres du palais Rospoli.","start":3,"end":9,"inf":"promettre","tense":"passe-simple","person":2,"work":0,"chapter":36},
  {"id":"f7cfd3729e","text":"Il courut au secrétaire, l’ouvrit, dans le tiroir indiqué trouva le portefeuille, et dans le portefeuille la lettre de crédit.","start":3,"end":9,"inf":"courir","tense":"passe-simple","person":2,"work":0,"chapter":37},
  {"id":"e6c8c89dc2","text":"Franz allait donner l’ordre qu’on fît venir maître Pastrini, lorsqu’il le vit apparaître en personne sur le seuil de sa porte.","start":34,"end":37,"inf":"faire","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":37},
  {"id":"f2b980f0a6","text":"En même temps ils virent au milieu de l’obscurité briller sur le canon d’une carabine le reflet de leur propre torche.","start":18,"end":24,"inf":"voir","tense":"passe-simple","person":5,"work":0,"chapter":37},
  {"id":"7d0e5780bc","text":"Mais tout ce qui sortait de la bouche de cet homme avait, malgré son caractère original, un tel cachet de simplicité, que l’on ne pouvait supposer qu’il dût mentir.","start":153,"end":156,"inf":"devoir","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":40},
  {"id":"d9e463a917","text":"Encore faudrait-il, chère mère, pour que le conseil me fût profitable, que je susse d’avance de quoi me méfier.","start":78,"end":83,"inf":"savoir","tense":"subjonctif-imparfait","person":0,"work":0,"chapter":41},
  {"id":"8cd32fc83e","text":"Vous n’auriez certes pas exigé que je vinsse.","start":38,"end":44,"inf":"venir","tense":"subjonctif-imparfait","person":0,"work":0,"chapter":43},
  {"id":"7f99e580b2","text":"Vous vous arrêtez juste à l’endroit où il reçut le coup.","start":42,"end":47,"inf":"recevoir","tense":"passe-simple","person":2,"work":0,"chapter":43},
  {"id":"3a9953212c","text":"Puis voyant la salle d’en bas vide comme d’habitude et simplement gardée par son chien, il appela sa femme.","start":91,"end":97,"inf":"appeler","tense":"passe-simple","person":2,"work":0,"chapter":44},
  {"id":"578750a8c6","text":"Je montrai du doigt l’endroit où j’étais caché.","start":3,"end":10,"inf":"montrer","tense":"passe-simple","person":0,"work":0,"chapter":45},
  {"id":"b13bf28dd3","text":"Et il montra le trou par lequel j’avais passé effectivement.","start":6,"end":12,"inf":"montrer","tense":"passe-simple","person":2,"work":0,"chapter":45},
  {"id":"60cbb4e55a","text":"Et il écrivit les quelques lignes que je vous remis, et sur lesquelles Votre Excellence eut la bonté de me prendre à son service.","start":6,"end":13,"inf":"écrire","tense":"passe-simple","person":2,"work":0,"chapter":45},
  {"id":"2ca76b640b","text":"Dis donc, Maximilien, dis donc, Emmanuel, si nous le retrouvions jamais, il faudrait bien qu’il crût à la mémoire du cœur.","start":96,"end":100,"inf":"croire","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":50},
  {"id":"3cb2cd0233","text":"Et le lendemain, fidèle à sa promesse, il envoya la recette demandée.","start":42,"end":48,"inf":"envoyer","tense":"passe-simple","person":2,"work":0,"chapter":52},
  {"id":"ab6faaaa03","text":"Il ne lui fallut qu’un regard pour qu’elle comprît combien souffrait son aïeul et combien de choses il avait à lui dire.","start":43,"end":50,"inf":"comprendre","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":58},
  {"id":"e7ac47101c","text":"On lut à Noirtier une formule de testament vague, banale.","start":3,"end":6,"inf":"lire","tense":"passe-simple","person":2,"work":0,"chapter":59},
  {"id":"5c47f0b96d","text":"Il offrit sa main à la baronne, qui lui fit en descendant un geste imperceptible pour tout autre que pour Monte-Cristo.","start":3,"end":9,"inf":"offrir","tense":"passe-simple","person":2,"work":0,"chapter":62},
  {"id":"a6ba1b1db0","text":"Il offrit une place dans son landau à Madame Danglars, afin qu’elle eût les soins de sa femme.","start":3,"end":9,"inf":"offrir","tense":"passe-simple","person":2,"work":0,"chapter":64},
  {"id":"93c7731d3b","text":"dit tout bas l’homme au mouchoir rouge, que vous voulussiez bien m’épargner la peine de retourner à Paris à pied.","start":49,"end":59,"inf":"vouloir","tense":"subjonctif-imparfait","person":4,"work":0,"chapter":64},
  {"id":"62bff9a512","text":"Danglars ne la regarda même pas, quoiqu’elle fît tout ce qu’elle put pour s’évanouir.","start":45,"end":48,"inf":"faire","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":65},
  {"id":"5d8b50bba4","text":"Rue Guénégaud, elle monta en fiacre en désignant, comme le but de sa course, la rue du Harlay.","start":20,"end":25,"inf":"monter","tense":"passe-simple","person":2,"work":0,"chapter":67},
  {"id":"8ddcfdc899","text":"Je pensai que l’assassin, ayant déterré le coffre et croyant que c’était un trésor, avait voulu s’en emparer, l’avait emporté.","start":3,"end":9,"inf":"penser","tense":"passe-simple","person":0,"work":0,"chapter":67},
  {"id":"837993063f","text":"Le visiteur, soit qu’il comprît le désir de l’abbé, soit qu’il fût au bout de ses questions, se leva à son tour.","start":24,"end":31,"inf":"comprendre","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":69},
  {"id":"95ac359f66","text":"Il en résulta que, pour la première fois depuis le dîner d’Auteuil, il dormit la nuit suivante avec quelque tranquillité.","start":71,"end":77,"inf":"dormir","tense":"passe-simple","person":2,"work":0,"chapter":69},
  {"id":"3ba02ece4c","text":"Morrel tourmenta si bien les siennes, qu’elles finirent par marquer huit heures et demie à six heures.","start":47,"end":55,"inf":"finir","tense":"passe-simple","person":5,"work":0,"chapter":73},
  {"id":"d5ef3fe655","text":"Morrel, glacé d’effroi, tenait d’une main son front, de l’autre comprimait son cœur, dont il craignait qu’on entendît les battements.","start":109,"end":117,"inf":"entendre","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":73},
  {"id":"e5433cb270","text":"Enfin, s’il venait, et qu’il trouvât ce jeune homme près de votre fille, il pourrait être mécontent.","start":29,"end":36,"inf":"trouver","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":76},
  {"id":"2f0a7f9ce2","text":"En effet, il était temps qu’elle arrivât à la grille.","start":33,"end":40,"inf":"arriver","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":78},
  {"id":"6660fc2d5b","text":"Et il lança devant lui sa casquette de livrée qui, manquant la chaise, tomba à terre et fit le tour de la chambre en roulant sur sa circonférence.","start":6,"end":11,"inf":"lancer","tense":"passe-simple","person":2,"work":0,"chapter":81},
  {"id":"b537ef724d","text":"Eh bien, on pourrait dévaliser tout le logis, sans qu’il entendît le moindre bruit.","start":57,"end":65,"inf":"entendre","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":82},
  {"id":"3540177e30","text":"c’est bien un miracle que Dieu a fait sans doute pour qu’il restât, malgré les précautions de l’assassin, une trace, une preuve, une dénonciation du crime.","start":60,"end":66,"inf":"rester","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":102},
  {"id":"c67d3e05f6","text":"Il appela une seconde fois, une troisième fois, même silence.","start":3,"end":9,"inf":"appeler","tense":"passe-simple","person":2,"work":0,"chapter":102},
  {"id":"d70227076f","text":"L’œil perçant de Monte-Cristo sonda tout d’un coup les bosquets d’ifs et de pins, et bientôt il perdit toute inquiétude.","start":96,"end":102,"inf":"perdre","tense":"passe-simple","person":2,"work":0,"chapter":105},
  {"id":"9010361421","text":"Ce personnage était un homme dont jamais le concierge lui-même n’avait pu voir la figure, soit qu’il entrât ou qu’il sortît.","start":101,"end":107,"inf":"entrer","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":106},
  {"id":"6b77d30a27","text":"Qu’y a-t-il de plus malheureux que l’homme qui a perdu le seul bien qu’il aimât et désirât au monde ?","start":74,"end":79,"inf":"aimer","tense":"subjonctif-imparfait","person":2,"work":0,"chapter":113},
  {"id":"de9ee44d86","text":"Il joua à la morra avec des facchino, perdit trois écus, et pour se consoler but un flacon de vin d’Orvietto.","start":3,"end":7,"inf":"jouer","tense":"passe-simple","person":2,"work":0,"chapter":114},
  {"id":"a7a48827a9","text":"Il serait important, comte, que je connusse la véritable cause…","start":35,"end":43,"inf":"connaître","tense":"subjonctif-imparfait","person":0,"work":0,"chapter":88},
  {"id":"5eda6e1619","text":"Mais parce que j’avais besoin que vous prissiez cet époux le plus tôt possible, pour certaines combinaisons commerciales que je suis en train d’établir en ce moment.","start":39,"end":47,"inf":"prendre","tense":"subjonctif-imparfait","person":4,"work":0,"chapter":95},
  {"id":"26adf10b38","text":"Elle retourna vers Louise, reprit la malle qu’elle avait un instant posée à terre, et toutes deux, suivant l’ombre projetée par la muraille, gagnèrent la voûte.","start":5,"end":13,"inf":"retourner","tense":"passe-simple","person":2,"work":0,"chapter":97},
  {"id":"a2d3591c85","text":"et depuis six mois le mari de Madame Georges avait disparu du bagne, sans qu’on sût ce qu’il était devenu.","start":80,"end":83,"inf":"savoir","tense":"subjonctif-imparfait","person":2,"work":1,"chapter":15},
  {"id":"0de9bfb5eb","text":"Bientôt elle lui avoua qu’elle partageait son amour, quoiqu’il dût, prévoyait-elle, leur causer de violents chagrins.","start":63,"end":66,"inf":"devoir","tense":"subjonctif-imparfait","person":2,"work":1,"chapter":14},
  {"id":"a9e4fd229b","text":"Elle dut accepter les prédictions à demi réalisées de la Highlandaise et persister dans sa croyance à une destinée souveraine.","start":5,"end":8,"inf":"devoir","tense":"passe-simple","person":2,"work":1,"chapter":17},
  {"id":"517b78eea5","text":"Le garçon conduisit un des moutons jusqu’à la porte.","start":10,"end":19,"inf":"conduire","tense":"passe-simple","person":2,"work":1,"chapter":2},
  {"id":"f3d25520b1","text":"dissipateur, joueur effréné, adonné à la plus basse crapule, il rendit sa femme très-malheureuse.","start":64,"end":70,"inf":"rendre","tense":"passe-simple","person":2,"work":1,"chapter":6},
  {"id":"4fcff55bc4","text":"Pour la première fois il parla en homme éclairé sur ses droits par un séjour de huit années en France.","start":25,"end":30,"inf":"parler","tense":"passe-simple","person":2,"work":1,"chapter":7},
  {"id":"8d80b362d3","text":"Mon père fut inflexible, elle tint sa promesse.","start":30,"end":34,"inf":"tenir","tense":"passe-simple","person":2,"work":1,"chapter":16},
  {"id":"dd625b9225","text":"De ce moment, nous vécûmes complètement retirées dans son appartement.","start":19,"end":26,"inf":"vivre","tense":"passe-simple","person":3,"work":1,"chapter":16},
  {"id":"31a48a5aea","text":"Je serais désolée que vous prissiez la peine de venir chez moi !…","start":27,"end":35,"inf":"prendre","tense":"subjonctif-imparfait","person":4,"work":1,"chapter":15},
  {"id":"b424f958c2","text":"Monsieur Badinot voudrait qu’il portât tout de suite cette lettre à son adresse.","start":32,"end":38,"inf":"porter","tense":"subjonctif-imparfait","person":2,"work":1,"chapter":4},
  {"id":"38b7ed43b9","text":"Il lança, sous ses lunettes, un regard de rage infernale à Polidori.","start":3,"end":8,"inf":"lancer","tense":"passe-simple","person":2,"work":1,"chapter":13},
  {"id":"56aaeb509c","text":"Et puis vous pourrez nous entretenir de vos chagrins s’ils durent encore, car j’aurai les miens.","start":59,"end":65,"inf":"devoir","tense":"passe-simple","person":5,"work":1,"chapter":2},
  {"id":"56099dbdbf","text":"et qu’il conduisît sa monture avec la plus grande précaution, des cris, des injures et des menaces s’élevèrent bientôt contre lui.","start":9,"end":18,"inf":"conduire","tense":"subjonctif-imparfait","person":2,"work":1,"chapter":3},
  {"id":"90a07facdd","text":"Il avait heureusement franchi le détroit que quelque secousse volcanique a creusé entre l’île de Calasareigne et l’île de Jaros.","start":3,"end":8,"inf":"avoir","tense":"imparfait","person":2,"work":0,"chapter":1},
  {"id":"3cc41efc20","text":"à la hauteur de Civita-Vecchia, nous avons perdu ce brave capitaine Leclère.","start":37,"end":42,"inf":"avoir","tense":"present","person":3,"work":0,"chapter":1},
  {"id":"a159045a60","text":"Il est arrivé à bon port, monsieur Morrel, et je crois que vous serez content sous ce rapport.","start":3,"end":6,"inf":"être","tense":"present","person":2,"work":0,"chapter":1},
  {"id":"b3bf265745","text":"Puis, comme on venait de dépasser la tour ronde.","start":15,"end":21,"inf":"venir","tense":"imparfait","person":2,"work":0,"chapter":1},
  {"id":"b312b9f750","text":"Eh bien, monsieur Morrel, dit Danglars, vous savez le malheur, n’est-ce pas ?","start":45,"end":50,"inf":"savoir","tense":"present","person":4,"work":0,"chapter":1},
  {"id":"a4497b7276","text":"Quant à perdre un jour et demi à l’île d’Elbe, il a eu tort.","start":50,"end":51,"inf":"avoir","tense":"present","person":2,"work":0,"chapter":1},
  {"id":"0a7ba2e083","text":"Vous voyez, dit Danglars, il se croit déjà capitaine, sur ma parole.","start":5,"end":10,"inf":"voir","tense":"present","person":4,"work":0,"chapter":1},
  {"id":"9cfba1e40a","text":"Il est jeune, je le sais bien, mais il me paraît tout à la chose, et fort expérimenté dans son état.","start":3,"end":6,"inf":"être","tense":"present","person":2,"work":0,"chapter":1},
  {"id":"e18d71e7b7","text":"Il m’a fait des questions sur le bâtiment, sur l’époque de son départ pour Marseille, sur la route qu’il avait suivie et sur la cargaison qu’il portait.","start":105,"end":110,"inf":"avoir","tense":"imparfait","person":2,"work":0,"chapter":1},
  {"id":"7b0207035b","text":"Dantès, vous direz à mon oncle que l’Empereur s’est souvenu de lui, et vous le verrez pleurer, le vieux grognard.","start":13,"end":18,"inf":"dire","tense":"futur","person":4,"work":0,"chapter":1},
  {"id":"3d4d7b729b","text":"Vous pouvez donc alors venir dîner avec nous ?","start":5,"end":11,"inf":"pouvoir","tense":"present","person":4,"work":0,"chapter":1},
  {"id":"c848702771","text":"demanda Dantès avec une certaine hésitation, et il se porte bien, que vous sachiez, mon père ?","start":75,"end":82,"inf":"savoir","tense":"subjonctif","person":4,"work":0,"chapter":1},
  {"id":"258f712c76","text":"dit l’armateur, cela ne m’étonne plus, qu’elle soit venue trois fois me demander des nouvelles du Pharaon.","start":47,"end":51,"inf":"être","tense":"subjonctif","person":2,"work":0,"chapter":1},
  {"id":"59d7f8c85d","text":"vous prendrez le temps que vous voudrez, Dantès.","start":5,"end":13,"inf":"prendre","tense":"futur","person":4,"work":0,"chapter":1},
  {"id":"9b161c1404","text":"Seulement, dans trois mois, il faudra que vous soyez là.","start":47,"end":52,"inf":"être","tense":"subjonctif","person":4,"work":0,"chapter":1},
  {"id":"6ce998b0c6","text":"Faites bien attention à ce que vous dites là, monsieur, car vous venez de répondre aux plus secrètes espérances de mon cœur.","start":36,"end":41,"inf":"dire","tense":"present","person":4,"work":0,"chapter":1},
  {"id":"2d0ff374a0","text":"Mais j’ai un associé, et vous savez le proverbe italien.","start":30,"end":35,"inf":"savoir","tense":"present","person":4,"work":0,"chapter":1},
  {"id":"57d6e6b9e5","text":"Rapportez-vous-en à moi pour avoir l’autre, et je ferai de mon mieux.","start":50,"end":55,"inf":"faire","tense":"futur","person":0,"work":0,"chapter":1},
  {"id":"fc0d9a69cb","text":"Si c’est comme comptable que vous me faites cette question je crois qu’il n’y a rien à dire et que vous serez content de la façon dont sa besogne est faite.","start":104,"end":109,"inf":"être","tense":"futur","person":4,"work":0,"chapter":1},
  {"id":"1a7bc0f30a","text":"Mais, demanda l’armateur, voyons, Dantès, si vous étiez capitaine du Pharaon, garderiez-vous Danglars avec plaisir ?","start":50,"end":55,"inf":"être","tense":"imparfait","person":4,"work":0,"chapter":1},
  {"id":"10906afb04","text":"Eh bien, mon cher duc, répondit Louis dix-huit, je vous crois mal renseigné, et je sais positivement, au contraire, qu’il fait très beau temps de ce côté-là.","start":122,"end":126,"inf":"faire","tense":"present","person":2,"work":0,"chapter":10},
  {"id":"0575ea2925","text":"Tout homme d’esprit qu’il était, Louis dix-huit aimait la plaisanterie facile.","start":26,"end":31,"inf":"être","tense":"imparfait","person":2,"work":0,"chapter":10},
  {"id":"a7f8893f24","text":"Je vous dis à gauche et vous cherchez à droite.","start":29,"end":37,"inf":"chercher","tense":"present","person":4,"work":0,"chapter":10},
  {"id":"6eb9fe72b8","text":"Vous devez trouver le rapport du ministre de la police en date d’hier…","start":5,"end":10,"inf":"devoir","tense":"present","person":4,"work":0,"chapter":10},
  {"id":"37a9bedc49","text":"Volontiers, duc, sous vos auspices je recevrai qui vous voudrez.","start":38,"end":46,"inf":"recevoir","tense":"futur","person":0,"work":0,"chapter":10},
  {"id":"4cd7b562b5","text":"Et moi, Sire, dit Monsieur de Blacas, je vais chercher mon messager.","start":41,"end":45,"inf":"aller","tense":"present","person":0,"work":0,"chapter":10},
  {"id":"bd1f708b27","text":"Mais mon messager est comme le cerf dont vous parlez, car il vient de faire deux cent vingt lieues en poste, et cela en trois jours à peine.","start":46,"end":52,"inf":"parler","tense":"present","person":4,"work":0,"chapter":10},
  {"id":"7c4397654c","text":"Et, pardieu, vous connaissez de nom son père.","start":18,"end":28,"inf":"connaître","tense":"present","person":4,"work":0,"chapter":10},
  {"id":"932e7251fc","text":"D’abord, et avant toutes choses, monsieur, le mal est-il aussi grand, à votre avis, que l’on veut me le faire croire ?","start":93,"end":97,"inf":"vouloir","tense":"present","person":2,"work":0,"chapter":10},
  {"id":"d7e96524f1","text":"À cette heure, il doit avoir quitté l’île d’Elbe pour aller où ?","start":18,"end":22,"inf":"devoir","tense":"present","person":2,"work":0,"chapter":10},
  {"id":"094f14d3dc","text":"S’il descendait en Toscane, il mettrait le pied en pays ennemi.","start":5,"end":15,"inf":"descendre","tense":"imparfait","person":2,"work":0,"chapter":10},
  {"id":"54c1188d76","text":"S’il descend en France, ce sera avec une poignée d’hommes, et nous en viendrons facilement à bout, exécré comme il l’est par la population.","start":5,"end":12,"inf":"descendre","tense":"present","person":2,"work":0,"chapter":10},
  {"id":"e3cebfdf16","text":"Sire, s’écria le duc de Blacas, ce n’est pas un homme comme Monsieur Dandré que l’on peut accuser de trahison.","start":85,"end":89,"inf":"pouvoir","tense":"present","person":2,"work":0,"chapter":11},
  {"id":"9b2170a321","text":"Villefort souriait intérieurement, car il sentait grandir son importance.","start":42,"end":49,"inf":"sentir","tense":"imparfait","person":2,"work":0,"chapter":11},
  {"id":"a0070f8c3a","text":"Le ridicule, monsieur, vous ne savez pas ce que c’est, en France, et cependant vous devriez le savoir.","start":84,"end":91,"inf":"devoir","tense":"conditionnel","person":4,"work":0,"chapter":11},
  {"id":"fc655f165c","text":"Ne m’accordez pas plus que je ne mérite, Sire, pour ne revenir jamais sur la première idée que vous aurez conçue de moi.","start":100,"end":105,"inf":"avoir","tense":"futur","person":4,"work":0,"chapter":11},
  {"id":"6d5e4a37f7","text":"Villefort s’était appuyé au dossier d’un fauteuil car à mesure que le ministre de la Police parlait, il sentait ses jambes se dérober sous lui.","start":104,"end":111,"inf":"sentir","tense":"imparfait","person":2,"work":0,"chapter":11},
  {"id":"40b78eac14","text":"Vous chercherez cet homme, monsieur, dit le roi au ministre de la Police.","start":5,"end":15,"inf":"chercher","tense":"futur","person":4,"work":0,"chapter":11},
  {"id":"ff43518de3","text":"monsieur, dit le ministre de la Police à Villefort en sortant des Tuileries, vous entrez par la bonne porte et votre fortune est faite.","start":82,"end":88,"inf":"entrer","tense":"present","person":4,"work":0,"chapter":11},
  {"id":"768373acb4","text":"Il allait se mettre à table lorsque le timbre de la sonnette retentit sous une main franche et ferme.","start":3,"end":9,"inf":"aller","tense":"imparfait","person":2,"work":0,"chapter":11},
  {"id":"a88660a919","text":"Eh bien, moi, en échange de votre histoire, continua Noirtier, je vais vous apprendre une nouvelle.","start":66,"end":70,"inf":"aller","tense":"present","person":0,"work":0,"chapter":12},
  {"id":"1c5ff48ba8","text":"Si cette lettre était tombée entre les mains d’un autre, à cette heure, mon père, vous seriez fusillé, peut-être.","start":87,"end":93,"inf":"être","tense":"conditionnel","person":4,"work":0,"chapter":12},
  {"id":"6d4a1acb8e","text":"On croyait pouvoir compter sur le général Quesnel.","start":3,"end":10,"inf":"croire","tense":"imparfait","person":2,"work":0,"chapter":12},
  {"id":"cec1f1a82e","text":"on nous l’avait recommandé de l’île d’Elbe, l’un de nous va chez lui, l’invite à se rendre rue Saint-Jacques à une assemblée où il trouvera des amis.","start":131,"end":139,"inf":"trouver","tense":"futur","person":2,"work":0,"chapter":12},
  {"id":"92584b8ccf","text":"Est-ce que jamais je me suis avisé de vous dire à vous, quand vous exercez votre métier de royaliste, et que vous faites couper la tête à l’un des miens.","start":114,"end":120,"inf":"faire","tense":"present","person":4,"work":0,"chapter":12},
  {"id":"99b79c79ed","text":"Mon cher ami, l’Empereur est, en ce moment, sur la route de Grenoble, le dix ou le douze il sera à Lyon, et le vingt ou le vingt-cinq à Paris.","start":92,"end":96,"inf":"être","tense":"futur","person":2,"work":0,"chapter":12},
  {"id":"b3e0dbc6c8","text":"Il n’a avec lui que quelques hommes, et l’on enverra contre lui des armées.","start":45,"end":52,"inf":"envoyer","tense":"futur","person":2,"work":0,"chapter":12},
  {"id":"2e4cd8749d","text":"Celui que vous appelez à Paris l’ogre de Corse, qui s’appelle encore l’usurpateur à Nevers, s’appelle déjà Bonaparte à Lyon, et l’Empereur à Grenoble.","start":15,"end":22,"inf":"appeler","tense":"present","person":4,"work":0,"chapter":12},
  {"id":"fc102a9a37","text":"Les soldats, que vous croyez mourants de faim, écrasés de fatigue, prêts à déserter, s’augmentent comme les atomes de neige autour de la boule qui se précipite.","start":22,"end":28,"inf":"croire","tense":"present","person":4,"work":0,"chapter":12},
  {"id":"64630c2dc5","text":"Aujourd’hui, vous servez Napoléon, et vous devez le protéger.","start":18,"end":24,"inf":"servir","tense":"present","person":4,"work":0,"chapter":13},
  {"id":"387da0413b","text":"Mais le retour miraculeux dont nous venons d’être témoins m’a prouvé que je me trompais.","start":36,"end":42,"inf":"venir","tense":"present","person":3,"work":0,"chapter":13},
  {"id":"a2aa24e88d","text":"Il aura été transporté à Fenestrelle, à Pignerol, aux Îles Sainte-Marguerite, ce que l’on appelle dépaysé, en termes d’administration.","start":3,"end":7,"inf":"avoir","tense":"futur","person":2,"work":0,"chapter":13},
  {"id":"e0dfeb9126","text":"Qu’il vienne quand il voudra, sa place lui sera gardée.","start":22,"end":28,"inf":"vouloir","tense":"futur","person":2,"work":0,"chapter":13},
  {"id":"9bebef8699","text":"Oui, reprit Villefort, mais il lira une pétition envoyée par moi, apostillée par moi, adressée directement par moi.","start":31,"end":35,"inf":"lire","tense":"futur","person":2,"work":0,"chapter":13},
  {"id":"c91c8f272c","text":"Oui, monsieur, songeons que le pauvre garçon attend, souffre et se désespère peut-être.","start":45,"end":51,"inf":"attendre","tense":"present","person":2,"work":0,"chapter":13},
  {"id":"41d5b421e2","text":"La meilleure apostille que je puisse mettre, monsieur, est de certifier véritable tout ce que vous dites dans cette demande.","start":99,"end":104,"inf":"dire","tense":"present","person":4,"work":0,"chapter":13},
  {"id":"7892e8952f","text":"cet homme-là ne se fût jamais tué, car il espérait toujours.","start":42,"end":50,"inf":"espérer","tense":"imparfait","person":2,"work":0,"chapter":13},
  {"id":"5cec102f97","text":"il habitait depuis si longtemps une tombe qu’il pouvait bien se regarder comme mort.","start":3,"end":11,"inf":"habiter","tense":"imparfait","person":2,"work":0,"chapter":14},
  {"id":"d9bfb33b2c","text":"vous pourriez être victime de l’un de ces actes.","start":5,"end":13,"inf":"pouvoir","tense":"conditionnel","person":4,"work":0,"chapter":14},
  {"id":"429d8382ae","text":"C’était, comme on le voit, un homme plein d’humanité que cet inspecteur, et bien digne des fonctions philanthropiques qu’il remplissait.","start":124,"end":135,"inf":"remplir","tense":"imparfait","person":2,"work":0,"chapter":14},
  {"id":"cf2a234b7b","text":"Mais je crois que vous trouverez contre lui des notes terribles.","start":23,"end":32,"inf":"trouver","tense":"futur","person":4,"work":0,"chapter":14},
  {"id":"81256c7cf4","text":"Je pourrai donc me fier aux notes qu’il a laissées sur vous ou qu’il me donnera ?","start":3,"end":10,"inf":"pouvoir","tense":"futur","person":0,"work":0,"chapter":14},
  {"id":"91f7dd7a09","text":"Vous connaissez votre personne, répondit ce dernier souriant.","start":5,"end":15,"inf":"connaître","tense":"present","person":4,"work":0,"chapter":14},
  {"id":"42ad6c444a","text":"Gardez-le donc pour le jour où vous sortirez de prison.","start":36,"end":44,"inf":"sortir","tense":"futur","person":4,"work":0,"chapter":14},
  {"id":"4ebad6484c","text":"Oui, j’abandonnerai six millions, et je me contenterai du reste si l’on veut me rendre la liberté.","start":72,"end":76,"inf":"vouloir","tense":"present","person":2,"work":0,"chapter":14},
  {"id":"342a490763","text":"Sur ma parole, dit l’inspecteur à demi-voix, si l’on ne savait que cet homme est fou, il parle avec un accent si convaincu qu’on croirait qu’il dit la vérité.","start":129,"end":137,"inf":"croire","tense":"conditionnel","person":2,"work":0,"chapter":14},
  {"id":"f76476cf1b","text":"vous me ramènerez dans ce même cachot, où je resterai éternellement, et où je mourrai sans plus rien demander ni à vous ni à personne.","start":45,"end":53,"inf":"rester","tense":"futur","person":0,"work":0,"chapter":14},
  {"id":"13dc8a0b7c","text":"Au moins, les galériens étaient dans la société de leurs semblables, ils respiraient l’air, ils voyaient le ciel.","start":96,"end":104,"inf":"voir","tense":"imparfait","person":5,"work":0,"chapter":15},
  {"id":"20eef459bc","text":"Il voyait Dieu éclatant à chaque mot qu’il prononçait.","start":3,"end":9,"inf":"voir","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"1197f13ab1","text":"Quand on me servira mon repas du matin et mon repas du soir, avait-il pensé, je jetterai les aliments par la fenêtre et j’aurai l’air de les avoir mangés.","start":80,"end":88,"inf":"jeter","tense":"futur","person":0,"work":0,"chapter":15},
  {"id":"1c33e05f20","text":"Il devait avoir vingt-cinq ou vingt-six ans, il lui restait cinquante ans à vivre à peu près, c’est-à-dire deux fois ce qu’il avait vécu.","start":3,"end":9,"inf":"devoir","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"3cc8bf469c","text":"Le lendemain il ne voyait plus, il entendait à peine.","start":35,"end":44,"inf":"entendre","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"e6a68527fe","text":"Edmond posa sur la table le pain qu’il tenait déjà presque à portée de sa bouche, et alla se recoucher.","start":39,"end":45,"inf":"tenir","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"7fcae5b16a","text":"Si au contraire c’est un prisonnier, le bruit que je ferai l’effrayera.","start":53,"end":58,"inf":"faire","tense":"futur","person":0,"work":0,"chapter":15},
  {"id":"23eb354796","text":"Il cessera son travail et ne le reprendra que ce soir, quand il croira tout le monde couché et endormi.","start":64,"end":70,"inf":"croire","tense":"futur","person":2,"work":0,"chapter":15},
  {"id":"6d1e91e5fb","text":"En effet, au bout d’une heure, la pierre était tirée du mur, où elle faisait une excavation de plus d’un pied et demi de diamètre.","start":69,"end":76,"inf":"faire","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"62d34de7f6","text":"Mais vous ne m’abandonnerez pas, vous ne me laisserez pas seul, vous viendrez à moi, ou vous me permettrez d’aller à vous ?","start":69,"end":77,"inf":"venir","tense":"futur","person":4,"work":0,"chapter":15},
  {"id":"634ae8e186","text":"Nous fuirons ensemble, et si nous ne pouvons fuir, nous parlerons, vous des gens que vous aimez, moi des gens que j’aime.","start":56,"end":65,"inf":"parler","tense":"futur","person":3,"work":0,"chapter":15},
  {"id":"1a2a46746b","text":"Je n’aimais que lui et une jeune fille qu’on appelait Mercédès.","start":45,"end":53,"inf":"appeler","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"f23773d868","text":"Le pis aller, s’il restait prisonnier, était d’avoir un compagnon.","start":19,"end":26,"inf":"rester","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"7e5032f597","text":"Les plaintes qu’on met en commun sont presque des prières.","start":19,"end":22,"inf":"mettre","tense":"present","person":2,"work":0,"chapter":15},
  {"id":"c1dcf0dc42","text":"Au moindre bruit qu’il entendait dans le corridor, il bondissait vers la porte.","start":23,"end":32,"inf":"entendre","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"dac4e89e2f","text":"Une fois ou deux, cette crainte qu’on le séparât de cet homme qu’il ne connaissait point, et que cependant il aimait déjà comme un ami, lui passa par le cerveau.","start":110,"end":116,"inf":"aimer","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"8448a58117","text":"Dantès ne répondit rien, il craignait que l’émotion de sa voix ne le trahît.","start":28,"end":37,"inf":"craindre","tense":"imparfait","person":2,"work":0,"chapter":15},
  {"id":"fec08139e8","text":"Il le remercia de sa cordialité avec une certaine chaleur, quoique sa déception eût été grande de trouver un second cachot où il croyait rencontrer la liberté.","start":129,"end":136,"inf":"croire","tense":"imparfait","person":2,"work":0,"chapter":16},
  {"id":"c5b590cd87","text":"Nous tomberions dans les caves qui ferment évidemment à la clef et nous serions pris.","start":5,"end":15,"inf":"tomber","tense":"conditionnel","person":3,"work":0,"chapter":16},
  {"id":"8704b2dbf9","text":"Vous voyez bien qu’il est impossible de fuir par votre cachot.","start":5,"end":10,"inf":"voir","tense":"present","person":4,"work":0,"chapter":16},
  {"id":"175a267994","text":"Vous verrez cela, jeune homme, dit-il en se retournant vers Dantès, et en le regardant avec des yeux brillants et profonds, comme en devaient avoir les prophètes.","start":5,"end":11,"inf":"voir","tense":"futur","person":4,"work":0,"chapter":16},
  {"id":"6052a02a55","text":"N’êtes-vous pas, dit Dantès, commençant à partager l’opinion de son geôlier, qui était l’opinion générale au château d’If, le prêtre que l’on croit…","start":142,"end":147,"inf":"croire","tense":"present","person":2,"work":0,"chapter":16},
  {"id":"7f94398eaf","text":"Comment, dit-il, pouvant être libre, vous seriez retenu par un semblable scrupule ?","start":42,"end":48,"inf":"être","tense":"conditionnel","person":4,"work":0,"chapter":16},
  {"id":"271f18b14c","text":"Ce double mouvement du globe qu’il habitait, et dont cependant il ne s’apercevait pas, lui semblait presque impossible.","start":35,"end":43,"inf":"habiter","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"8f93738633","text":"L’abbé alla vers la cheminée, déplaça avec le ciseau qu’il tenait toujours à la main la pierre qui formait autrefois l’âtre et qui cachait une cavité assez profonde.","start":59,"end":65,"inf":"tenir","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"f4957c85f7","text":"Et l’abbé, ouvrant un lambeau de ses vêtements, montra à Dantès une arête longue, aiguë et encore enfilée, qu’il portait sur lui.","start":113,"end":120,"inf":"porter","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"c3827f3c54","text":"Dantès alors raconta ce qu’il appelait son histoire, et qui se bornait à un voyage dans l’Inde et à deux où trois voyages dans le Levant.","start":30,"end":38,"inf":"appeler","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"53a79c5e9c","text":"C’est clair comme le jour, dit-il, il faut que vous ayez eu le cœur bien naïf et bien bon pour n’avoir pas deviné la chose tout d’abord.","start":52,"end":56,"inf":"avoir","tense":"subjonctif","person":4,"work":0,"chapter":17},
  {"id":"b15add935c","text":"Près de la table où ils buvaient étaient un encrier, du papier, des plumes.","start":24,"end":32,"inf":"boire","tense":"imparfait","person":5,"work":0,"chapter":17},
  {"id":"bcb060f1a6","text":"Vous devriez m’apprendre un peu de ce que vous savez, dit Dantès, ne fût-ce que pour ne pas vous ennuyer avec moi.","start":5,"end":12,"inf":"devoir","tense":"conditionnel","person":4,"work":0,"chapter":17},
  {"id":"e474d184a9","text":"Il savait déjà, d’ailleurs, l’italien et un peu de romaïque, qu’il avait appris dans ses voyages d’Orient.","start":3,"end":9,"inf":"savoir","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"5bbf785489","text":"Il tombait dans de profondes rêveries, soupirait involontairement, se levait tout à coup, croisait les bras et se promenait sombre autour de sa prison.","start":3,"end":10,"inf":"tomber","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"8319bcb22f","text":"Alors, dit l’abbé, nous pourrons exécuter notre dessein.","start":24,"end":32,"inf":"pouvoir","tense":"futur","person":3,"work":0,"chapter":17},
  {"id":"238a7b95f6","text":"Ce plan était si simple qu’il devait réussir.","start":30,"end":36,"inf":"devoir","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"102f3c2304","text":"Merci, dit l’abbé, frissonnant de tous ses membres comme s’il sortait d’une eau glacée.","start":62,"end":69,"inf":"sortir","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"6ad8f58379","text":"il allait être sept heures et Dantès n’avait pas eu le loisir de mesurer le temps.","start":3,"end":9,"inf":"aller","tense":"imparfait","person":2,"work":0,"chapter":17},
  {"id":"daccf1fd3a","text":"La troisième fois, j’en resterai paralysé entièrement ou je mourrai sur le coup.","start":60,"end":67,"inf":"mourir","tense":"futur","person":0,"work":0,"chapter":17},
  {"id":"e87f88b056","text":"Eh bien, nous attendrons huit jours, un mois, deux mois, s’il le faut.","start":14,"end":24,"inf":"attendre","tense":"futur","person":3,"work":0,"chapter":17},
  {"id":"ff9377bcb5","text":"Le jour où vous vous sentirez assez de forces pour nager, eh bien, ce jour-là, nous mettrons notre projet à exécution.","start":84,"end":92,"inf":"mettre","tense":"futur","person":3,"work":0,"chapter":17},
  {"id":"50aca3ee42","text":"Quant à votre paralysie, elle ne me gêne pas, je vous prendrai sur mes épaules et je nagerai en vous soutenant.","start":85,"end":92,"inf":"nager","tense":"futur","person":0,"work":0,"chapter":17},
  {"id":"52ed0e6043","text":"je resterai donc ici jusqu’à ce que sonne l’heure de ma délivrance, qui ne peut plus être maintenant que celle de la mort.","start":3,"end":11,"inf":"rester","tense":"futur","person":0,"work":0,"chapter":17},
  {"id":"89661348eb","text":"En outre, il pouvait compter sur un prix très brillant de la vente de ces deux chapeaux.","start":13,"end":20,"inf":"pouvoir","tense":"imparfait","person":2,"work":0,"chapter":18},
  {"id":"67150fc5b9","text":"Il restait une troisième part de spéculation, qui va apparaître bientôt.","start":3,"end":10,"inf":"rester","tense":"imparfait","person":2,"work":0,"chapter":18},
  {"id":"ec49dda0fd","text":"César pensait qu’on pouvait user de l’un de ces moyens qu’il tenait toujours à la disposition de ses amis intimes, savoir.","start":20,"end":27,"inf":"pouvoir","tense":"imparfait","person":2,"work":0,"chapter":18},
  {"id":"015d243e1f","text":"Il y avait aussi la bague à tête de lion, que César passait à son doigt lorsqu’il donnait de certaines poignées de main.","start":82,"end":89,"inf":"donner","tense":"imparfait","person":2,"work":0,"chapter":18},
  {"id":"bbadf9ec63","text":"C’était la déclaration du cardinal Spada et le testament que l’on cherchait depuis si longtemps ?","start":66,"end":75,"inf":"chercher","tense":"imparfait","person":2,"work":0,"chapter":18},
  {"id":"7521dc7eac","text":"si nous mettons la main sur cette fortune, nous pourrons en jouir sans remords.","start":8,"end":15,"inf":"mettre","tense":"present","person":3,"work":0,"chapter":18},
  {"id":"527098200b","text":"Ses traits étaient bouleversés par ces horribles symptômes qu’il connaissait déjà et qui l’avaient tant épouvanté lorsqu’ils étaient apparus pour la première fois.","start":65,"end":76,"inf":"connaître","tense":"imparfait","person":2,"work":0,"chapter":19},
  {"id":"ee856d065d","text":"Eh bien, mon ami dit Faria résigné, vous comprenez, n’est-ce pas ?","start":41,"end":50,"inf":"comprendre","tense":"present","person":4,"work":0,"chapter":19},
  {"id":"e22b6dbd38","text":"C’est l’affection que nous appelons la monomanie, dit le médecin.","start":27,"end":35,"inf":"appeler","tense":"present","person":3,"work":0,"chapter":19},
  {"id":"749000ceda","text":"Le pauvre abbé n’avait qu’à ne pas tant se presser, et il aurait eu son requiem.","start":58,"end":64,"inf":"avoir","tense":"conditionnel","person":2,"work":0,"chapter":19},
  {"id":"a34ca1baf1","text":"Aussi je veux que du premier argent que je toucherai vous ayez une petite maison, avec un jardin pour planter vos clématites, vos capucines et vos chèvrefeuilles….","start":58,"end":62,"inf":"avoir","tense":"subjonctif","person":4,"work":0,"chapter":2},
  {"id":"2d7beefe22","text":"Mais, qu’as-tu donc, père, on dirait que tu te trouves mal ?","start":30,"end":36,"inf":"dire","tense":"conditionnel","person":2,"work":0,"chapter":2},
  {"id":"bb39052c3d","text":"Il me l’a rappelée, en me disant que si je ne payais pas pour toi il irait se faire payer chez Monsieur Morrel.","start":69,"end":74,"inf":"aller","tense":"conditionnel","person":2,"work":0,"chapter":2},
  {"id":"da39e40d4d","text":"on croirait, si l’on me voyait acheter trop de choses à la fois, que j’ai été obligé d’attendre ton retour pour les acheter.","start":3,"end":11,"inf":"croire","tense":"conditionnel","person":2,"work":0,"chapter":2},
  {"id":"ecebc09f4d","text":"Si nous allions du même côté, nous nous arrêterons à la Réserve, et, tout en buvant un verre de vin de La Malgue, nous attendrions des nouvelles.","start":119,"end":130,"inf":"attendre","tense":"conditionnel","person":3,"work":0,"chapter":2},
  {"id":"e72179d0ea","text":"Si pendant le trajet les fossoyeurs reconnaissaient qu’ils portaient un vivant au lieu de porter un mort, Dantès ne leur donnait pas le temps de se reconnaître.","start":59,"end":68,"inf":"porter","tense":"imparfait","person":5,"work":0,"chapter":20},
  {"id":"83c646885b","text":"D’un vigoureux coup de couteau il ouvrait le sac depuis le haut jusqu’en bas, profitait de leur terreur et s’échappait.","start":34,"end":41,"inf":"ouvrir","tense":"imparfait","person":2,"work":0,"chapter":20},
  {"id":"07fbf23755","text":"S’ils voulaient l’arrêter, il jouait du couteau.","start":6,"end":15,"inf":"vouloir","tense":"imparfait","person":5,"work":0,"chapter":20},
  {"id":"ff16967368","text":"S’il se trompait, si au contraire la terre était trop pesante, il mourait étouffé, et, tant mieux !","start":66,"end":73,"inf":"mourir","tense":"imparfait","person":2,"work":0,"chapter":20},
  {"id":"8539e94794","text":"Une exclamation de satisfaction indiqua que le fossoyeur avait trouvé ce qu’il cherchait.","start":79,"end":88,"inf":"chercher","tense":"imparfait","person":2,"work":0,"chapter":20},
  {"id":"ca7410bcbd","text":"Il écoutait, penché sur la cime des flots, si aucune rumeur n’arrivait jusque lui.","start":3,"end":11,"inf":"écouter","tense":"imparfait","person":2,"work":0,"chapter":21},
  {"id":"77d90bba59","text":"Il nageait cependant, et déjà le château terrible s’était un peu fondu dans la vapeur nocturne.","start":3,"end":10,"inf":"nager","tense":"imparfait","person":2,"work":0,"chapter":21},
  {"id":"9d349b4ffc","text":"À vingt pas de lui s’élevait une masse de rochers bizarres qu’on prendrait pour un foyer immense pétrifié au moment de sa plus ardente combustion.","start":65,"end":74,"inf":"prendre","tense":"conditionnel","person":2,"work":0,"chapter":21},
  {"id":"45a01d5909","text":"Elle venait du port de Marseille et gagnait le large en poussant l’écume étincelante devant la proue aiguë qui ouvrait une route plus facile à ses flancs rebondis.","start":5,"end":11,"inf":"venir","tense":"imparfait","person":2,"work":0,"chapter":21},
  {"id":"eb62382307","text":"quelle fable inventer dont ils puissent être la dupe ?","start":31,"end":39,"inf":"pouvoir","tense":"subjonctif","person":5,"work":0,"chapter":21},
  {"id":"9374849e2f","text":"Ils aimeront mieux me vendre que de faire une bonne action stérile.","start":4,"end":12,"inf":"aimer","tense":"futur","person":5,"work":0,"chapter":21},
  {"id":"b1db146f19","text":"Dantès alors laissa glisser la solive dont il pensait n’avoir plus besoin, et nagea vigoureusement pour épargner la moitié du chemin à ceux qui venaient à lui.","start":46,"end":53,"inf":"penser","tense":"imparfait","person":2,"work":0,"chapter":21},
  {"id":"e950b53eb9","text":"Son premier regard fut pour voir quelle direction elle suivait.","start":55,"end":62,"inf":"suivre","tense":"imparfait","person":2,"work":0,"chapter":21},
  {"id":"3ef9f30ee2","text":"Oui, s’il dit vrai, dit le patron d’un air de doute mais dans l’état où est le pauvre diable, on promet beaucoup, quitte à tenir ce que l’on peut.","start":97,"end":103,"inf":"promettre","tense":"present","person":2,"work":0,"chapter":21},
  {"id":"959d5eee05","text":"Je tiendrai plus que je n’ai promis, dit Dantès.","start":3,"end":11,"inf":"tenir","tense":"futur","person":0,"work":0,"chapter":21},
  {"id":"826a31f023","text":"Quand vous voudrez, reprit Dantès en se relevant.","start":11,"end":18,"inf":"vouloir","tense":"futur","person":4,"work":0,"chapter":21},
  {"id":"29f2a7bd3a","text":"Parce que nous irions donner droit sur l’île de Rion.","start":15,"end":21,"inf":"aller","tense":"conditionnel","person":3,"work":0,"chapter":21},
  {"id":"4287913b79","text":"Ce que vous donnez aux camarades, vous me le donnerez, et tout sera dit.","start":12,"end":18,"inf":"donner","tense":"present","person":4,"work":0,"chapter":21},
  {"id":"e296baecf0","text":"Dantès était sur la voie qu’il voulait parcourir, et marchait au but qu’il voulait atteindre.","start":31,"end":38,"inf":"vouloir","tense":"imparfait","person":2,"work":0,"chapter":22},
  {"id":"85512b8846","text":"Là, il ferait en toute liberté ses recherches.","start":7,"end":13,"inf":"faire","tense":"conditionnel","person":2,"work":0,"chapter":22},
  {"id":"298e8c0be1","text":"La prison avait rendu Edmond prudent, et il aurait bien voulu ne rien risquer.","start":44,"end":50,"inf":"avoir","tense":"conditionnel","person":2,"work":0,"chapter":22},
  {"id":"743112042b","text":"La prime était énorme si l’on réussissait, il s’agissait de cinquante à soixante piastres par homme.","start":30,"end":41,"inf":"réussir","tense":"imparfait","person":2,"work":0,"chapter":22},
  {"id":"e9cba88104","text":"Il descendait dans les grottes aux pavés d’émeraudes, aux parois de rubis, aux stalactites de diamants.","start":3,"end":13,"inf":"descendre","tense":"imparfait","person":2,"work":0,"chapter":23},
  {"id":"b737568539","text":"Puis il revenait au jour, et ces pierreries s’étaient changées en simples cailloux.","start":8,"end":16,"inf":"revenir","tense":"imparfait","person":2,"work":0,"chapter":23},
  {"id":"8f032a8abd","text":"On faisait plus de deux lieues et demie à l’heure.","start":3,"end":10,"inf":"faire","tense":"imparfait","person":2,"work":0,"chapter":23},
  {"id":"4a224d831a","text":"On comprend qu’il ne fut point question de déjeuner pour Dantès.","start":3,"end":11,"inf":"comprendre","tense":"present","person":2,"work":0,"chapter":23},
  {"id":"d2db0902cc","text":"Que veux-tu donc que nous fassions, Maltais, dit-il, nous ne pouvons t’abandonner ainsi, et nous ne pouvons rester, cependant ?","start":26,"end":34,"inf":"faire","tense":"subjonctif","person":3,"work":0,"chapter":23},
  {"id":"545d2c329e","text":"il craignait fort, en un pareil moment, un accident semblable à celui qu’il avait si habilement et si heureusement simulé.","start":3,"end":12,"inf":"craindre","tense":"imparfait","person":2,"work":0,"chapter":24},
  {"id":"e65faee1b5","text":"Mais Dantès se rappela les termes du testament, qu’il savait par cœur.","start":54,"end":60,"inf":"savoir","tense":"imparfait","person":2,"work":0,"chapter":24},
  {"id":"6d708e97a7","text":"Bientôt, il se sentit plus calme et partant plus heureux, car de cette heure seulement il commençait à croire à sa félicité.","start":90,"end":100,"inf":"commencer","tense":"imparfait","person":2,"work":0,"chapter":24},
  {"id":"51be364999","text":"Vous trouvez que je ne suis pas riche, n’est-ce pas monsieur l’abbé ?","start":5,"end":12,"inf":"trouver","tense":"present","person":4,"work":0,"chapter":26},
  {"id":"b64d52384e","text":"Car s’il sortait de prison, sa fortune était assurée par la vente seule de ce diamant.","start":9,"end":16,"inf":"sortir","tense":"imparfait","person":2,"work":0,"chapter":26},
  {"id":"85ec872099","text":"Caderousse sembla chercher sous les vêtements de l’abbé le dépôt dont il parlait.","start":73,"end":80,"inf":"parler","tense":"imparfait","person":2,"work":0,"chapter":26},
  {"id":"eb36a5db08","text":"Vous vendrez ce diamant, vous ferez cinq parts et vous les partagerez entre ces bons amis, les seuls êtres qui m’aient aimé sur la terre !","start":5,"end":12,"inf":"vendre","tense":"futur","person":4,"work":0,"chapter":26},
  {"id":"cf32c1f6e5","text":"Non pas que je tienne à savoir les choses que vous voudriez me cacher.","start":51,"end":59,"inf":"vouloir","tense":"conditionnel","person":4,"work":0,"chapter":26},
  {"id":"3d4d7f3851","text":"Attendez, reprit Caderousse, on pourrait nous interrompre à l’endroit le plus intéressant, et ce serait désagréable.","start":32,"end":40,"inf":"pouvoir","tense":"conditionnel","person":2,"work":0,"chapter":26},
  {"id":"eda934c950","text":"Eh bien, en ce cas, dit Caderousse, je veux, je dirai même plus, je dois vous détromper sur ces amitiés que le pauvre Edmond croyait sincères et dévouées.","start":48,"end":53,"inf":"dire","tense":"futur","person":0,"work":0,"chapter":27},
  {"id":"008ef6b11a","text":"Ce qu’il trouvait d’éloquentes paroles et de pitoyables supplications, je ne saurais vous le redire, monsieur.","start":9,"end":17,"inf":"trouver","tense":"imparfait","person":2,"work":0,"chapter":27},
  {"id":"e6ea55a2ac","text":"De jour en jour, il vivait plus seul et plus isolé.","start":20,"end":26,"inf":"vivre","tense":"imparfait","person":2,"work":0,"chapter":27},
  {"id":"89a51f4354","text":"il vendait peu à peu ce qu’il avait pour vivre.","start":3,"end":10,"inf":"vendre","tense":"imparfait","person":2,"work":0,"chapter":27},
  {"id":"78ea65beb8","text":"Sa fortune grandissait déjà, et elle grandissait avec sa fortune.","start":37,"end":48,"inf":"grandir","tense":"imparfait","person":2,"work":0,"chapter":27},
  {"id":"26475a64c0","text":"Elle apprenait le dessin, elle apprenait la musique, elle apprenait tout.","start":5,"end":14,"inf":"apprendre","tense":"imparfait","person":2,"work":0,"chapter":27},
  {"id":"c805548360","text":"Mais il vient toujours un moment où il se souvient, et en voici la preuve.","start":8,"end":13,"inf":"venir","tense":"present","person":2,"work":0,"chapter":27},
  {"id":"aaf91ea505","text":"Seulement je demanderai un droit de courtage.","start":13,"end":23,"inf":"demander","tense":"futur","person":0,"work":0,"chapter":28},
  {"id":"b82493e360","text":"Vous tenez des registres d’entrée et de sortie ?","start":5,"end":10,"inf":"tenir","tense":"present","person":4,"work":0,"chapter":28},
  {"id":"981a2317fe","text":"Il pensait sans doute que les prisonniers morts au château d’If étaient enterrés dans un cimetière ordinaire.","start":3,"end":10,"inf":"penser","tense":"imparfait","person":2,"work":0,"chapter":28},
  {"id":"1e89f7fe60","text":"Il sembla à l’étranger qu’on montait doucement l’escalier et que les pas, qui étaient ceux de plusieurs personnes, s’arrêtaient sur le palier.","start":29,"end":36,"inf":"monter","tense":"imparfait","person":2,"work":0,"chapter":29},
  {"id":"148fc08591","text":"Mais il n’en est pas moins vrai que l’eau montait toujours, pas de beaucoup, de deux pouces peut-être par heure, mais enfin elle montait.","start":129,"end":136,"inf":"monter","tense":"imparfait","person":2,"work":0,"chapter":29},
  {"id":"64c2a2c440","text":"Mais prenez, prenez, et si vous trouvez un bon service, entrez-y, vous êtes libres.","start":32,"end":39,"inf":"trouver","tense":"present","person":4,"work":0,"chapter":29},
  {"id":"461e01358b","text":"Eh bien, vous en ferez construire d’autres, nous attendrons.","start":49,"end":59,"inf":"attendre","tense":"futur","person":3,"work":0,"chapter":29},
  {"id":"8dd6118e82","text":"Mademoiselle, dit l’étranger, vous recevrez un jour une lettre signée…","start":35,"end":43,"inf":"recevoir","tense":"futur","person":4,"work":0,"chapter":29},
  {"id":"aff449319d","text":"Elle arrivait on ne savait d’où et parlait une langue inconnue.","start":5,"end":13,"inf":"arriver","tense":"imparfait","person":2,"work":0,"chapter":3},
  {"id":"3637e1a84e","text":"Vous me porterez bonheur, et je deviendrai riche.","start":32,"end":42,"inf":"devenir","tense":"futur","person":0,"work":0,"chapter":3},
  {"id":"9da0523282","text":"Je veux dire, Mercédès, que vous n’êtes si dure et si cruelle pour moi que parce que vous attendez quelqu’un qui est ainsi vêtu.","start":90,"end":98,"inf":"attendre","tense":"present","person":4,"work":0,"chapter":3},
  {"id":"c92261a9fb","text":"on dirait deux amants qui marchent côte à côte et la main dans la main.","start":3,"end":9,"inf":"dire","tense":"conditionnel","person":2,"work":0,"chapter":3},
  {"id":"84e45489a2","text":"Depuis la veille au soir, elles attendaient Maximilien.","start":32,"end":43,"inf":"attendre","tense":"imparfait","person":5,"work":0,"chapter":30},
  {"id":"33b0dc56c4","text":"À toi peut-être on donnera le temps qu’on m’aurait refusé.","start":19,"end":26,"inf":"donner","tense":"futur","person":2,"work":0,"chapter":30},
  {"id":"e02f2a0e1b","text":"Morrel ne se retourna point, il attendait ces mots de Coclès.","start":32,"end":41,"inf":"attendre","tense":"imparfait","person":2,"work":0,"chapter":30},
  {"id":"ad5a62620b","text":"si Votre Excellence voulait, lui dit le patron, elle ferait une belle chasse !","start":53,"end":59,"inf":"faire","tense":"conditionnel","person":2,"work":0,"chapter":31},
  {"id":"dab48ef7a6","text":"Heureusement que les mariniers étaient dans leurs parages habituels et qu’ils connaissaient jusqu’au moindre rocher de l’archipel toscan.","start":78,"end":91,"inf":"connaître","tense":"imparfait","person":5,"work":0,"chapter":31},
  {"id":"6360dbd32e","text":"Ainsi vous craignez que ce feu ne nous annonce mauvaise compagnie ?","start":11,"end":19,"inf":"craindre","tense":"present","person":4,"work":0,"chapter":31},
  {"id":"9f75932b0f","text":"Lorsqu’on le lui demande, il répond qu’il se nomme Simbad le marin.","start":29,"end":35,"inf":"répondre","tense":"present","person":2,"work":0,"chapter":31},
  {"id":"0c63b33205","text":"Il sembla à Franz qu’il fermait les yeux, et qu’à travers le dernier regard qu’il jetait autour de lui il entrevoyait la statue pudique qui se voilait entièrement.","start":82,"end":88,"inf":"jeter","tense":"imparfait","person":2,"work":0,"chapter":31},
  {"id":"d9b87f7b00","text":"Je voulais poignarder l’homme, mais la femme m’a dit que s’il arrivait malheur à son fiancé, elle se tuerait.","start":62,"end":70,"inf":"arriver","tense":"imparfait","person":2,"work":0,"chapter":4},
  {"id":"a58060144b","text":"Vous disiez, monsieur, reprit Fernand, que vous voudriez me tirer de peine.","start":48,"end":56,"inf":"vouloir","tense":"conditionnel","person":4,"work":0,"chapter":4},
  {"id":"bf0c25c8da","text":"pour vous tirer de peine il suffit que Dantès n’épouse pas celle que vous aimez et le mariage peut très bien manquer, ce me semble, sans que Dantès meure.","start":74,"end":79,"inf":"aimer","tense":"present","person":4,"work":0,"chapter":4},
  {"id":"e90dff701b","text":"Je veux qu’on me dise pourquoi on mettrait Dantès en prison.","start":34,"end":42,"inf":"mettre","tense":"conditionnel","person":2,"work":0,"chapter":4},
  {"id":"2221585c52","text":"C’est toi qui vois trouble, dit Danglars, il suit tout droit le chemin des Vieilles-Infirmeries.","start":45,"end":49,"inf":"suivre","tense":"present","person":2,"work":0,"chapter":4},
  {"id":"db13bbb3a6","text":"De temps en temps, il regardait du côté de Marseille, et alors un tremblement nerveux et involontaire faisait frissonner ses membres.","start":22,"end":31,"inf":"regarder","tense":"imparfait","person":2,"work":0,"chapter":5},
  {"id":"8d987a99bb","text":"Allons donc, dit-il, est-ce que vous craindriez quelque chose ?","start":37,"end":47,"inf":"craindre","tense":"conditionnel","person":4,"work":0,"chapter":5},
  {"id":"af450c8c81","text":"Essaie un peu de faire le mari, et tu verras comme tu seras reçu !","start":38,"end":44,"inf":"voir","tense":"futur","person":1,"work":0,"chapter":5},
  {"id":"2267e89955","text":"dit, sans trop savoir ce qu’il disait, le père Dantès.","start":31,"end":37,"inf":"dire","tense":"imparfait","person":2,"work":0,"chapter":5},
  {"id":"231719915c","text":"Si l’on trouvait sur lui quelque lettre qui le compromette, ceux qui l’auraient soutenu passeraient pour ses complices.","start":8,"end":16,"inf":"trouver","tense":"imparfait","person":2,"work":0,"chapter":5},
  {"id":"5a2c5466c1","text":"madame, dit Villefort, ma profession et surtout le temps dans lequel nous vivons m’ordonnent d’être sévère.","start":74,"end":80,"inf":"vivre","tense":"present","person":3,"work":0,"chapter":6},
  {"id":"9a7da45597","text":"dit Villefort tout en lisant et en pâlissant, à mesure qu’il lisait.","start":61,"end":67,"inf":"lire","tense":"imparfait","person":2,"work":0,"chapter":7},
  {"id":"c0cca5c928","text":"Et de temps en temps il regardait Edmond, comme si son regard eût pu briser cette barrière invisible qui enferme dans le cœur les secrets que garde la bouche.","start":24,"end":33,"inf":"regarder","tense":"imparfait","person":2,"work":0,"chapter":7},
  {"id":"a61334d693","text":"Après nombre de détours dans le corridor qu’il suivait, Dantès vit s’ouvrir une porte avec un guichet de fer.","start":47,"end":54,"inf":"suivre","tense":"imparfait","person":2,"work":0,"chapter":8},
  {"id":"4a8f1de58b","text":"La consigne ne vous défend pas de m’apprendre ce que je saurai dans dix minutes, dans une demi heure, dans une heure peut-être.","start":56,"end":62,"inf":"savoir","tense":"futur","person":0,"work":0,"chapter":8},
  {"id":"e150a55af4","text":"voilà comme vous tenez votre parole de marin.","start":17,"end":22,"inf":"tenir","tense":"present","person":4,"work":0,"chapter":8},
  {"id":"6df4b43e2a","text":"Il parlait l’italien comme un Toscan, l’espagnol comme un enfant de la Vieille-Castille.","start":3,"end":10,"inf":"parler","tense":"imparfait","person":2,"work":0,"chapter":8},
  {"id":"6d7cdef1df","text":"Eh bien, dit Dantès, si tu ne m’apportes plus à manger, je mourrai de faim, voilà tout.","start":59,"end":66,"inf":"mourir","tense":"futur","person":0,"work":0,"chapter":8},
  {"id":"7322e61318","text":"dit Dantès en reposant son escabeau sur le sol et en s’asseyant dessus, la tête basse et les yeux hagards, comme s’il devenait réellement insensé.","start":118,"end":126,"inf":"devenir","tense":"imparfait","person":2,"work":0,"chapter":8},
  {"id":"89ae9f8e85","text":"L’homme dont vous parlez, dit brusquement Villefort, est un grand coupable, et je ne puis rien faire pour lui, mademoiselle.","start":18,"end":24,"inf":"parler","tense":"present","person":4,"work":0,"chapter":9},
  {"id":"ddc0e15792","text":"Elle aimait Villefort, Villefort allait partir au moment de devenir son mari.","start":5,"end":11,"inf":"aimer","tense":"imparfait","person":2,"work":0,"chapter":9},
  {"id":"d22721cc7f","text":"Villefort ne pouvait dire quand il reviendrait, et Renée, au lieu de plaindre Dantès, maudit l’homme qui, par son crime, la séparait de son amant.","start":35,"end":46,"inf":"revenir","tense":"conditionnel","person":2,"work":0,"chapter":9},
  {"id":"c4b11094fd","text":"Il se laissa aller sans réfléchir, sans penser à ce charme divin qu’il y a dans les choses de la nature, surtout lorsqu’on sort d’un rêve fantastique.","start":123,"end":127,"inf":"sortir","tense":"present","person":2,"work":0,"chapter":32},
  {"id":"7a084ba7d0","text":"Mais il espère que vous l’excuserez quand vous saurez qu’une affaire très pressante l’appelle à Malaga.","start":47,"end":53,"inf":"savoir","tense":"futur","person":4,"work":0,"chapter":32},
  {"id":"e7a6078316","text":"D’abord son yacht n’est pas un navire, c’est un oiseau, et il rendrait trois nœuds sur douze à une frégate.","start":62,"end":70,"inf":"rendre","tense":"conditionnel","person":2,"work":0,"chapter":32},
  {"id":"e827b1683a","text":"Soyez tranquille, cher ami, ils viendront tout seuls.","start":32,"end":41,"inf":"venir","tense":"futur","person":5,"work":0,"chapter":32},
  {"id":"d075b65c6b","text":"Il arrivera dix à douze mille voyageurs, répondit Franz, lesquels rendront la difficulté plus grande encore.","start":3,"end":11,"inf":"arriver","tense":"futur","person":2,"work":0,"chapter":33},
  {"id":"d049350dd7","text":"vous perdrez donc la différence et ce sera votre faute.","start":5,"end":12,"inf":"perdre","tense":"futur","person":4,"work":0,"chapter":33},
  {"id":"c70b1f244f","text":"Dépeignez-nous le, afin que si nous le rencontrions par hasard dans le monde, comme Jean Sbogar ou Lara, nous puissions au moins le reconnaître.","start":110,"end":119,"inf":"pouvoir","tense":"subjonctif","person":3,"work":0,"chapter":33},
  {"id":"568214368a","text":"Ah çà, fit Franz, arrêtant maître Pastrini au moment où il ouvrait la bouche, vous dites que vous avez connu Luigi Vampa tout enfant.","start":59,"end":66,"inf":"ouvrir","tense":"imparfait","person":2,"work":0,"chapter":33},
  {"id":"d2abbcbcc9","text":"Ce désir était devenu un besoin, et ils comprenaient plutôt la mort qu’une séparation d’un seul jour.","start":40,"end":52,"inf":"comprendre","tense":"imparfait","person":5,"work":0,"chapter":33},
  {"id":"143b1be5fd","text":"C’était lui qui s’occupait à réorganiser une troupe, et qui marchait sur les traces de Decesaris et de Gasparone, qu’il espérait bientôt surpasser.","start":120,"end":128,"inf":"espérer","tense":"imparfait","person":2,"work":0,"chapter":33},
  {"id":"f2c26bff96","text":"On donnait pour tout délai au père douze heures, c’est-à-dire jusqu’au lendemain neuf heures du matin.","start":3,"end":10,"inf":"donner","tense":"imparfait","person":2,"work":0,"chapter":33},
  {"id":"e065c67290","text":"À mesure qu’ils entraient dans le cercle de la lumière projetée par le foyer, on s’apercevait de la pâleur de la jeune fille et de la pâleur du bandit.","start":16,"end":25,"inf":"entrer","tense":"imparfait","person":5,"work":0,"chapter":33},
  {"id":"beca18352d","text":"C’est fâcheux, dit le brigadier, car celui que nous cherchons, c’est le chef.","start":52,"end":61,"inf":"chercher","tense":"present","person":3,"work":0,"chapter":33},
  {"id":"c9be2b90f7","text":"Je donnerai dix mille piastres à quelqu’un que je sais, et qui obtiendra que l’exécution de Peppino soit remise à l’année prochaine.","start":3,"end":11,"inf":"donner","tense":"futur","person":0,"work":0,"chapter":34},
  {"id":"0120615142","text":"Grâce à son costume, il arrivera jusqu’au pied de l’échafaud et remettra la bulle au chef de la confrérie, qui la remettra au bourreau.","start":24,"end":32,"inf":"arriver","tense":"futur","person":2,"work":0,"chapter":34},
  {"id":"9f5042fdde","text":"Et encore avait-il eu le temps de s’informer de la pièce qu’on jouait et des acteurs qui la joueraient.","start":63,"end":69,"inf":"jouer","tense":"imparfait","person":2,"work":0,"chapter":34},
  {"id":"daa500bb57","text":"Et, s’il n’y avait pas la fenêtre du palais Rospoli pour faire compensation à ce que nous perdons, je crois que j’en reviendrais à ma première idée.","start":90,"end":97,"inf":"perdre","tense":"present","person":3,"work":0,"chapter":34},
  {"id":"b13c5f0505","text":"Quant à Albert, comme il n’avait pas les mêmes motifs que Franz d’être matinal, il dormait encore de son mieux.","start":83,"end":90,"inf":"dormir","tense":"imparfait","person":2,"work":0,"chapter":34},
  {"id":"7441589421","text":"D’ailleurs vous m’avez fait dire que vous viendriez, et je me suis tenu à votre disposition.","start":42,"end":51,"inf":"venir","tense":"conditionnel","person":4,"work":0,"chapter":35},
  {"id":"6458e6b75a","text":"Mais vous perdez, je vous en préviens, une chose fort curieuse, répondit le comte.","start":10,"end":16,"inf":"perdre","tense":"present","person":4,"work":0,"chapter":35},
  {"id":"9013a99541","text":"quand on tue un homme d’Église, on prend une arme plus convenable qu’un chenet, surtout quand cet homme d’église est peut-être notre père.","start":35,"end":40,"inf":"prendre","tense":"present","person":2,"work":0,"chapter":35},
  {"id":"2f08d31591","text":"Eh bien, passons par la rue du Cours, nous enverrons la voiture nous attendre sur la piazza del Popolo, par la strada del Babuino.","start":43,"end":52,"inf":"envoyer","tense":"futur","person":3,"work":0,"chapter":35},
  {"id":"c3b3f88131","text":"On m’avait promis qu’il mourrait avant moi, on n’a pas le droit de me faire mourir seul, je ne le veux pas !","start":24,"end":32,"inf":"mourir","tense":"conditionnel","person":2,"work":0,"chapter":35},
  {"id":"cb3cfb1049","text":"Vous entendez, monsieur, on me renvoie à vous, dit la comtesse.","start":5,"end":13,"inf":"entendre","tense":"present","person":4,"work":0,"chapter":36},
  {"id":"f1b1c6ade1","text":"En effet, le lendemain à neuf heures il entrait dans la chambre de Franz avec un tailleur chargé de huit ou dix costumes de paysans romains.","start":40,"end":47,"inf":"entrer","tense":"imparfait","person":2,"work":0,"chapter":36},
  {"id":"0a1321fc21","text":"Il me semble que si vous vous donniez la peine de chercher, vous trouveriez quelque moyen qui simplifierait beaucoup la négociation, dit Franz.","start":65,"end":75,"inf":"trouver","tense":"conditionnel","person":4,"work":0,"chapter":37},
  {"id":"e61fabe09d","text":"Que Votre Excellence m’interroge, et je répondrai.","start":40,"end":49,"inf":"répondre","tense":"futur","person":0,"work":0,"chapter":37},
  {"id":"ca70ed9af3","text":"Il l’avait déjà remercié la veille, mais il comprenait qu’un service comme celui qu’il lui avait rendu valait bien deux remerciements.","start":44,"end":54,"inf":"comprendre","tense":"imparfait","person":2,"work":0,"chapter":38},
  {"id":"63ef372309","text":"Ainsi, quand vous reviendrez à Paris vous me trouverez homme posé et peut-être père de famille.","start":18,"end":28,"inf":"revenir","tense":"futur","person":4,"work":0,"chapter":38},
  {"id":"74579d0c79","text":"Vous que je n’attendais que le dernier, vous arrivez à dix heures moins cinq minutes, lorsque le rendez-vous définitif n’est qu’à dix heures et demie !","start":45,"end":52,"inf":"arriver","tense":"present","person":4,"work":0,"chapter":39},
  {"id":"b67a4dccfe","text":"Je devinai que vous deviendriez le mien, monsieur le baron, dit Morrel.","start":20,"end":31,"inf":"devenir","tense":"conditionnel","person":4,"work":0,"chapter":39},
  {"id":"8b95ab25f8","text":"bon, voilà que vous vous fâchez, et que vous tombez sur nos pauvres agents.","start":45,"end":51,"inf":"tomber","tense":"present","person":4,"work":0,"chapter":39},
  {"id":"71d0f89243","text":"Mais dit Beauchamp, qui en sa qualité de journaliste était fort incrédule, vous portez donc toujours cette drogue sur vous ?","start":80,"end":86,"inf":"porter","tense":"present","person":4,"work":0,"chapter":40},
  {"id":"12421480ab","text":"Je parlerai du comte au ministre, et il faudra bien que nous sachions qui il est.","start":3,"end":11,"inf":"parler","tense":"futur","person":0,"work":0,"chapter":40},
  {"id":"40ab64764e","text":"À mesure que nous passerons d’une chambre à l’autre, nous ouvrirons les fenêtres pour que vous respiriez.","start":58,"end":67,"inf":"ouvrir","tense":"futur","person":3,"work":0,"chapter":41},
  {"id":"8a32c9a15c","text":"Je crois que vous devenez fou, maître Bertuccio, dit froidement le comte.","start":18,"end":25,"inf":"devenir","tense":"present","person":4,"work":0,"chapter":43},
  {"id":"0df9a785b4","text":"d’abord, vous achetez une maison juste à Auteuil, cette maison est celle où j’ai commis un assassinat.","start":14,"end":21,"inf":"acheter","tense":"present","person":4,"work":0,"chapter":43},
  {"id":"2b7968d306","text":"Vous descendez au jardin juste par l’escalier où il est descendu.","start":5,"end":14,"inf":"descendre","tense":"present","person":4,"work":0,"chapter":43},
  {"id":"6c6934e9e8","text":"Il nous disait que l’armée était licenciée et qu’il revenait par Châteauroux, Clermont-Ferrand, le Puy et Nîmes.","start":52,"end":60,"inf":"revenir","tense":"imparfait","person":2,"work":0,"chapter":44},
  {"id":"219f37b968","text":"Mais je savais qu’il existait à Paris un hospice où on reçoit ces pauvres créatures.","start":55,"end":61,"inf":"recevoir","tense":"present","person":2,"work":0,"chapter":44},
  {"id":"c23f7229d4","text":"À votre service, monsieur le comte, où l’on apprend toutes choses.","start":44,"end":51,"inf":"apprendre","tense":"present","person":2,"work":0,"chapter":44},
  {"id":"e87e68bec7","text":"qu’à cela ne tienne, dit Caderousse, je retournerai avec vous à Beaucaire pour chercher les cinq autres mille francs.","start":40,"end":51,"inf":"retourner","tense":"futur","person":0,"work":0,"chapter":44},
  {"id":"e0fd7336a7","text":"Il ira prévenir les magistrats, il faudra retrouver l’abbé Busoni, et les abbés qui donnent des diamants de deux mille louis sont rares.","start":3,"end":6,"inf":"aller","tense":"futur","person":2,"work":0,"chapter":44},
  {"id":"ab270dece6","text":"Ses lèvres étaient si minces, qu’au lieu de saillir en dehors elles rentraient dans la bouche.","start":68,"end":78,"inf":"rentrer","tense":"imparfait","person":5,"work":0,"chapter":46},
  {"id":"5a21cdb5df","text":"Quand vous en aurez connaissance, vous irez la visiter, et si vous êtes content, vous l’achèterez à votre nom.","start":39,"end":43,"inf":"aller","tense":"futur","person":4,"work":0,"chapter":46},
  {"id":"14138a6d7a","text":"Mais, vous le savez, nous vivons sous un gouvernement populaire, et moi, je suis un représentant des intérêts du peuple.","start":26,"end":32,"inf":"vivre","tense":"present","person":3,"work":0,"chapter":46},
  {"id":"ba89ff8283","text":"C’est un homme sage, comme il disait tout à l’heure.","start":30,"end":36,"inf":"dire","tense":"imparfait","person":2,"work":0,"chapter":46},
  {"id":"2a7d843114","text":"S’il me faut plus, reprit machinalement Monte-Cristo, nous mettrons plus.","start":59,"end":67,"inf":"mettre","tense":"futur","person":3,"work":0,"chapter":46},
  {"id":"9c88be1ff8","text":"Mais vous-même, monsieur, pouvez-vous dire cela, car, du moment où vous habitez la France, vous êtes naturellement soumis aux lois françaises.","start":72,"end":79,"inf":"habiter","tense":"present","person":4,"work":0,"chapter":48},
  {"id":"e7b0113963","text":"Non, seigneur, car le matin je penserai que tu viendras, et le soir je me rappellerai que tu es venu.","start":31,"end":39,"inf":"penser","tense":"futur","person":0,"work":0,"chapter":49},
  {"id":"5170260179","text":"Mais ils ne s’arrêteront pas là, nos jeunes gens, ils deviendront à leur tour millionnaires.","start":54,"end":65,"inf":"devenir","tense":"futur","person":5,"work":0,"chapter":50},
  {"id":"9c568370c5","text":"Je l’ai quitté il y a deux ou trois ans à Palerme et il partait pour les pays les plus fabuleux.","start":56,"end":63,"inf":"partir","tense":"imparfait","person":2,"work":0,"chapter":50},
  {"id":"bee69d15cb","text":"Madame de Villefort étendait la main pour sonner, et pour indiquer à la femme de chambre le lieu où elle trouverait Valentine, lorsque celle-ci entra.","start":105,"end":115,"inf":"trouver","tense":"conditionnel","person":2,"work":0,"chapter":52},
  {"id":"fc37af5d37","text":"Mademoiselle de Villefort aime peu le monde, et nous sortons rarement, dit la jeune femme.","start":53,"end":60,"inf":"sortir","tense":"present","person":3,"work":0,"chapter":52},
  {"id":"097ccc1697","text":"Supposez que vous sachiez d’avance de quel poison on doit user contre vous…","start":18,"end":25,"inf":"savoir","tense":"subjonctif","person":4,"work":0,"chapter":52},
  {"id":"26b6dd9c42","text":"Parmi ces légumes, il choisissait le plus honnête de tous, un chou, par exemple.","start":22,"end":33,"inf":"choisir","tense":"imparfait","person":2,"work":0,"chapter":52},
  {"id":"2bed17614f","text":"Vous demandez ce que c’est que la comtesse G…","start":5,"end":13,"inf":"demander","tense":"present","person":4,"work":0,"chapter":53},
  {"id":"4548acc6a7","text":"J’espère que lorsqu’il me verra sortir il sortira.","start":42,"end":49,"inf":"sortir","tense":"futur","person":2,"work":0,"chapter":53},
  {"id":"926dd0f6c7","text":"Cela fera monter les fonds, elle établira son coup de bourse là-dessus, et elle perdra certainement lorsque Beauchamp écrira le lendemain dans son journal.","start":80,"end":86,"inf":"perdre","tense":"futur","person":2,"work":0,"chapter":54},
  {"id":"b2353038ac","text":"Vous entendez, Monsieur le major Bartolomeo Cavalcanti, un homme de la plus vieille noblesse d’Italie et dont Dante a pris la peine d’être le d’Hozier…","start":5,"end":13,"inf":"entendre","tense":"present","person":4,"work":0,"chapter":54},
  {"id":"365e003519","text":"Mais enfin Son Excellence pourrait me dire qui elle reçoit !","start":52,"end":58,"inf":"recevoir","tense":"present","person":2,"work":0,"chapter":54},
  {"id":"16a92c9421","text":"Si l’on apprenait quelque chose de cette séparation…","start":8,"end":17,"inf":"apprendre","tense":"imparfait","person":2,"work":0,"chapter":55},
  {"id":"b2318ae846","text":"À peine aurez-vous raconté à quelqu’un votre touchante histoire, qu’elle courra dans le monde complètement dénaturée.","start":73,"end":79,"inf":"courir","tense":"futur","person":2,"work":0,"chapter":56},
  {"id":"88ab7a03d0","text":"Car, pour éviter une faute, on tomberait dans une folie.","start":31,"end":40,"inf":"tomber","tense":"conditionnel","person":2,"work":0,"chapter":56},
  {"id":"55aabff3b0","text":"Je crois, mon cher fils, que vous regardez maintenant la France comme une seconde patrie ?","start":34,"end":42,"inf":"regarder","tense":"present","person":4,"work":0,"chapter":56},
  {"id":"29529a383e","text":"Je retournerai donc en Italie aussitôt que je pourrai.","start":3,"end":14,"inf":"retourner","tense":"futur","person":0,"work":0,"chapter":56},
  {"id":"c9bdab2c16","text":"Vous pensez donc que je puis croire aux promesses qu’on m’a faites ?","start":5,"end":11,"inf":"penser","tense":"present","person":4,"work":0,"chapter":56},
  {"id":"2093cb72e6","text":"Si vous achetez des chevaux, prenez-les chez Devedeux.","start":8,"end":15,"inf":"acheter","tense":"present","person":4,"work":0,"chapter":56},
  {"id":"4e9aeb9ba2","text":"Cependant, écoutez-moi, Valentine, et ne vous effrayez pas, car tant que je vivrai je ne serai pas à une autre.","start":76,"end":82,"inf":"vivre","tense":"futur","person":0,"work":0,"chapter":57},
  {"id":"95f32370fe","text":"S’il demandait Valentine, il fermait l’œil droit seulement.","start":5,"end":14,"inf":"demander","tense":"imparfait","person":2,"work":0,"chapter":58},
  {"id":"86e8e5ccf6","text":"S’il demandait Barrois, il fermait l’œil gauche.","start":5,"end":14,"inf":"demander","tense":"imparfait","person":2,"work":0,"chapter":58},
  {"id":"ed6d7b1472","text":"Vous m’arrêterez quand j’aurai atteint celui que vous croirez être le vôtre.","start":54,"end":61,"inf":"croire","tense":"futur","person":4,"work":0,"chapter":59},
  {"id":"f60c6d34a4","text":"Il arriverait que, ne les ayant pas répétés par négligence, je serais mis à l’amende.","start":3,"end":13,"inf":"arriver","tense":"conditionnel","person":2,"work":0,"chapter":61},
  {"id":"f206126d1f","text":"Avec cinq mille francs, vous achèterez une jolie petite maison et deux arpents de terre.","start":29,"end":38,"inf":"acheter","tense":"futur","person":4,"work":0,"chapter":61},
  {"id":"ecc9ccabc3","text":"mais je crois que vous devenez fou, mon brave Bertuccio, dit le comte.","start":23,"end":30,"inf":"devenir","tense":"present","person":4,"work":0,"chapter":62},
  {"id":"4448bc5d39","text":"Là, vous prendrez un cabriolet, afin de n’être point trop en retard.","start":9,"end":17,"inf":"prendre","tense":"futur","person":4,"work":0,"chapter":64},
  {"id":"f7bad47e6f","text":"On apprend que j’ai quitté Toulon sans donner congé, et l’on me reconduit de brigade en brigade jusqu’au bord de la Méditerranée.","start":3,"end":10,"inf":"apprendre","tense":"present","person":2,"work":0,"chapter":64},
  {"id":"5ed56062c9","text":"Et c’est moi que vous rendez responsable de cette perte ?","start":22,"end":28,"inf":"rendre","tense":"present","person":4,"work":0,"chapter":65},
  {"id":"3d00133f36","text":"que m’importe à moi, puisque vous payez les leçons que vous prenez sur votre cassette ?","start":60,"end":66,"inf":"prendre","tense":"present","person":4,"work":0,"chapter":65},
  {"id":"1aaf8a763d","text":"Cependant, n’importe, vous comprendrez que lorsque sept cent mille francs sortent de la poche de la femme, le mari s’en aperçoit toujours bien un peu.","start":27,"end":38,"inf":"comprendre","tense":"futur","person":4,"work":0,"chapter":66},
  {"id":"c61f1ec2f8","text":"Et je vois que je m’étais trompé, et que vous rentrez dans les fortunes du second ordre.","start":46,"end":53,"inf":"rentrer","tense":"present","person":4,"work":0,"chapter":66},
  {"id":"48a59bb547","text":"Comment, du fond de la tombe et du fond de nos cœurs où il dormait, est-il sorti comme un fantôme pour faire pâlir nos joues et rougir nos fronts ?","start":59,"end":66,"inf":"dormir","tense":"imparfait","person":2,"work":0,"chapter":67},
  {"id":"9e3cb0ed7e","text":"Ne serait-ce pas pour lui une bien douce vengeance, quand il apprendrait que je n’étais pas mort de son coup de poignard ?","start":61,"end":72,"inf":"apprendre","tense":"conditionnel","person":2,"work":0,"chapter":67},
  {"id":"39b7a80e8f","text":"C’est une perfection désespérante, et vous donnez à tous ceux qui vous entendent de graves envies de rester célibataires.","start":43,"end":49,"inf":"donner","tense":"present","person":4,"work":0,"chapter":68},
  {"id":"2c985f7969","text":"Le lendemain soir, ses ordres étaient exécutés, et voici les renseignements qu’il recevait.","start":82,"end":90,"inf":"recevoir","tense":"imparfait","person":2,"work":0,"chapter":69},
  {"id":"1cf66e13b2","text":"Une de ses manies était de ne vouloir pas absolument parler la langue française, qu’il écrivait cependant, assurait-on, avec une assez grande pureté.","start":87,"end":95,"inf":"écrire","tense":"imparfait","person":2,"work":0,"chapter":69},
  {"id":"5da0825851","text":"Je reviendrai donc ce soir à l’heure convenue, reprit le visiteur.","start":3,"end":13,"inf":"revenir","tense":"futur","person":0,"work":0,"chapter":69},
  {"id":"1710b47a10","text":"Nous espérons donc, monsieur l’abbé, qu’il n’y aura ni liens d’amitié ni considération humaine qui puissent vous engager à déguiser la vérité à la justice.","start":5,"end":13,"inf":"espérer","tense":"present","person":3,"work":0,"chapter":69},
  {"id":"cb33dd644d","text":"je vois qu’elle meurt d’envie de vous parler.","start":16,"end":21,"inf":"mourir","tense":"present","person":2,"work":0,"chapter":70},
  {"id":"5a176528f9","text":"N’enchaînez pas ces messieurs ici, monsieur le comte, dit-elle, ils aimeront autant, s’ils ne jouent pas, respirer au jardin qu’étouffer ici.","start":68,"end":76,"inf":"aimer","tense":"futur","person":5,"work":0,"chapter":70},
  {"id":"7619cef5d3","text":"Monsieur de Saint-Méran avait toujours dit que, s’il mourait loin de Paris, il désirait que son corps fût ramené dans le caveau de la famille.","start":53,"end":60,"inf":"mourir","tense":"imparfait","person":2,"work":0,"chapter":72},
  {"id":"1831e2adbe","text":"Vous vivrez avec nous, vous vivrez longtemps heureuse, aimée, honorée, et nous vous ferons oublier…","start":5,"end":11,"inf":"vivre","tense":"futur","person":4,"work":0,"chapter":72},
  {"id":"2e7463cfe7","text":"Écoutez, dit Morrel, ce n’est pas la première fois que vous pensez à la situation où nous sommes arrivés.","start":60,"end":66,"inf":"penser","tense":"present","person":4,"work":0,"chapter":73},
  {"id":"dd27affca7","text":"Vous suivrez donc votre fortune, telle que le sort vous le fera, et sans même essayer de la combattre ?","start":5,"end":12,"inf":"suivre","tense":"futur","person":4,"work":0,"chapter":73},
  {"id":"639425eec4","text":"Encore une fois, vous retournez le poignard dans la plaie !","start":22,"end":31,"inf":"retourner","tense":"present","person":4,"work":0,"chapter":73},
  {"id":"2f86afe52c","text":"Dans le silence on écoutait inutilement le bruit des pas.","start":19,"end":27,"inf":"écouter","tense":"imparfait","person":2,"work":0,"chapter":73},
  {"id":"59512b82fc","text":"Alors, dit en riant le général, nous courons un autre risque, celui de verser.","start":37,"end":44,"inf":"courir","tense":"present","person":3,"work":0,"chapter":75},
  {"id":"ea329a0fc2","text":"J’ai fait serment à Louis dix-huit, je tiendrai mon serment.","start":39,"end":47,"inf":"tenir","tense":"futur","person":0,"work":0,"chapter":75},
  {"id":"a01f0e6879","text":"Au moment où l’on commençait à laisser, à la manière anglaise, les cuillers dans les tasses, la porte se rouvrit, et Danglars reparut visiblement fort agité.","start":18,"end":28,"inf":"commencer","tense":"imparfait","person":2,"work":0,"chapter":76},
  {"id":"bff1148ad1","text":"nous rentrons dans les mystères d’Isis, et je ne suis pas initié.","start":5,"end":13,"inf":"rentrer","tense":"present","person":3,"work":0,"chapter":77},
  {"id":"470540f7ff","text":"dit Albert, ce ne serait pas la peine d’avoir une Grecque devant soi pour lui parler de tout ce dont on parlerait à une Parisienne.","start":104,"end":113,"inf":"parler","tense":"conditionnel","person":2,"work":0,"chapter":77},
  {"id":"bbca9742c1","text":"Puis, de temps en temps venait à lui un Albanais qui lui disait quelques mots auxquels je ne faisais pas attention, et auxquels il répondait du même son de voix.","start":131,"end":140,"inf":"répondre","tense":"imparfait","person":2,"work":0,"chapter":77},
  {"id":"e31ab9edd9","text":"Elle lui prépara l’eau glacée qu’il buvait à chaque instant, car, depuis sa retraite dans le kiosque, il était brûlé par une fièvre ardente.","start":36,"end":42,"inf":"boire","tense":"imparfait","person":2,"work":0,"chapter":77},
  {"id":"ebc61634ff","text":"Si vous mourez, mon maître, je veux mourir avec vous.","start":8,"end":14,"inf":"mourir","tense":"present","person":4,"work":0,"chapter":77},
  {"id":"ea4cf5d351","text":"Cependant il ne consentit à se retirer que sur la promesse qu’il verrait Valentine le lendemain soir.","start":65,"end":72,"inf":"voir","tense":"conditionnel","person":2,"work":0,"chapter":78},
  {"id":"7541677f8a","text":"Est-ce ou n’est-ce pas une comédie que nous jouons ?","start":44,"end":50,"inf":"jouer","tense":"present","person":3,"work":0,"chapter":78},
  {"id":"52e03bc71e","text":"Vous sentez cependant, dit Morcerf, que je ne puis me payer de vos réticences.","start":5,"end":11,"inf":"sentir","tense":"present","person":4,"work":0,"chapter":78},
  {"id":"e8d139ba25","text":"Si je suis votre ami, Morcerf, vous finirez par me le faire oublier avec des mots pareils à ceux de tout à l’heure…","start":36,"end":43,"inf":"finir","tense":"futur","person":4,"work":0,"chapter":78},
  {"id":"f31ada1c22","text":"Le fait est, dit Barrois, que je meurs de soif, et que je boirai bien volontiers un verre de limonade à votre santé.","start":58,"end":64,"inf":"boire","tense":"futur","person":0,"work":0,"chapter":79},
  {"id":"77cbce9e73","text":"Caderousse donna l’exemple et se mit à déjeuner de bon appétit, et en faisant l’éloge de tous les mets qu’il servait à son hôte.","start":109,"end":116,"inf":"servir","tense":"imparfait","person":2,"work":0,"chapter":81},
  {"id":"a34992b300","text":"La fenêtre où l’on travaillait était en face de l’ouverture par laquelle le comte plongeait son regard dans le cabinet.","start":19,"end":30,"inf":"travailler","tense":"imparfait","person":2,"work":0,"chapter":82},
  {"id":"d9ef2596f3","text":"Mais jurez-moi que vous ne me frapperez pas tandis que je descendrai.","start":58,"end":68,"inf":"descendre","tense":"futur","person":0,"work":0,"chapter":82},
  {"id":"424cdbb413","text":"Et à tous ceux qui le demandaient, on répondait qu’il était absent pour un voyage de quelques jours.","start":38,"end":47,"inf":"répondre","tense":"imparfait","person":2,"work":0,"chapter":84},
  {"id":"492fa47723","text":"Il m’a dit que votre vie était la sienne, et je lui ai promis que vous vivriez.","start":71,"end":78,"inf":"vivre","tense":"conditionnel","person":4,"work":0,"chapter":100},
  {"id":"beaf89a139","text":"Vous aimez mieux mourir alors, et faire mourir Maximilien !…","start":5,"end":10,"inf":"aimer","tense":"present","person":4,"work":0,"chapter":101},
  {"id":"06bd1e2778","text":"On changera de poison ou l’on augmentera la dose.","start":3,"end":11,"inf":"changer","tense":"futur","person":2,"work":0,"chapter":101},
  {"id":"fc7f34cde4","text":"Non, non, vous ne mourrez pas, et quelque chose qui vous arrive, vous me le promettez, vous ne vous plaindrez pas, vous espérerez ?","start":120,"end":129,"inf":"espérer","tense":"futur","person":4,"work":0,"chapter":101},
  {"id":"c350a1af3a","text":"Il dort, et c’est bien étrange, car la moindre contrariété le tient éveillé des nuits entières.","start":3,"end":7,"inf":"dormir","tense":"present","person":2,"work":0,"chapter":104},
  {"id":"64db41c4f5","text":"Mon crédit chez vous était de six millions, j’ai pris neuf cent mille francs, c’est cinq millions cent mille francs que vous restez me devoir.","start":125,"end":131,"inf":"rester","tense":"present","person":4,"work":0,"chapter":104},
  {"id":"07112ecb32","text":"Maximilien, dit Monte-Cristo, posons chacun de notre côté le masque que nous portons.","start":77,"end":84,"inf":"porter","tense":"present","person":3,"work":0,"chapter":105},
  {"id":"02b04df5a6","text":"Mais presque toujours, hiver ou été, c’était vers quatre heures qu’il prenait possession de son appartement, dans lequel il ne passait jamais la nuit.","start":70,"end":77,"inf":"prendre","tense":"imparfait","person":2,"work":0,"chapter":106},
  {"id":"28ce481d77","text":"Tant que les filets étaient bons, on prenait du poisson.","start":37,"end":44,"inf":"prendre","tense":"imparfait","person":2,"work":0,"chapter":106},
  {"id":"b6823ada28","text":"Tant qu’on vendait du poisson, on avait du fil pour entretenir les filets.","start":11,"end":18,"inf":"vendre","tense":"imparfait","person":2,"work":0,"chapter":106},
  {"id":"0340f5a5eb","text":"Ma mère, je partirai, dit Albert d’une voix calme et ferme, vous m’aimez trop pour me laisser près de vous oisif et inutile.","start":12,"end":20,"inf":"partir","tense":"futur","person":0,"work":0,"chapter":106},
  {"id":"8fad9df44c","text":"En effet, on lisait dans ce regard un sanglant reproche en même temps qu’une terrible menace.","start":13,"end":19,"inf":"lire","tense":"imparfait","person":2,"work":0,"chapter":108},
  {"id":"2d1f4d981d","text":"Il jouait cependant très passablement le prince.","start":3,"end":9,"inf":"jouer","tense":"imparfait","person":2,"work":0,"chapter":109},
  {"id":"233559e19b","text":"À cette question comme aux autres, je répondrai, monsieur le président, mais à son tour.","start":38,"end":47,"inf":"répondre","tense":"futur","person":0,"work":0,"chapter":110},
  {"id":"ca5cf3c89b","text":"Vous partez ainsi tout de suite, sans préparations, sans passeports ?","start":5,"end":11,"inf":"partir","tense":"present","person":4,"work":0,"chapter":112},
  {"id":"fefa8aa4f7","text":"On cherchera qui je suis, on demandera ce que je fais, on ignorera comment je vis, qu’importe !","start":3,"end":12,"inf":"chercher","tense":"futur","person":2,"work":0,"chapter":112},
  {"id":"83b62c1bb4","text":"Il offrait des millions si on voulait lui rendre la liberté.","start":3,"end":10,"inf":"offrir","tense":"imparfait","person":2,"work":0,"chapter":113},
  {"id":"ba2034f10c","text":"Oui, Excellence, répondit le patron, nous arrivons.","start":42,"end":50,"inf":"arriver","tense":"present","person":3,"work":0,"chapter":117},
  {"id":"9e2c1f114a","text":"Dix minutes après on carguait les voiles, et l’on jetait l’ancre à cinq cents pas d’un petit port.","start":50,"end":56,"inf":"jeter","tense":"imparfait","person":2,"work":0,"chapter":117},
  {"id":"120e0b1ad7","text":"Et si vous vouliez mourir, comte, vous sauriez mourir ainsi, vous ?","start":39,"end":46,"inf":"savoir","tense":"conditionnel","person":4,"work":0,"chapter":117},
  {"id":"290e174b55","text":"Sans moi vous mourriez tous deux, je vous rends l’un à l’autre.","start":14,"end":22,"inf":"mourir","tense":"conditionnel","person":4,"work":0,"chapter":117},
  {"id":"0feed9027a","text":"Elle m’avait fait demander pour savoir quand vous reviendriez.","start":50,"end":61,"inf":"revenir","tense":"conditionnel","person":4,"work":0,"chapter":85},
  {"id":"743181cf11","text":"Non, ce serait trop long, et puis j’ai besoin de cette fatigue que vous craignez pour moi, elle me fera du bien.","start":72,"end":80,"inf":"craindre","tense":"present","person":4,"work":0,"chapter":85},
  {"id":"0d0958454c","text":"Pas d’autre que de rendre celui que vous montez.","start":41,"end":47,"inf":"monter","tense":"present","person":4,"work":0,"chapter":85},
  {"id":"b576539e94","text":"Il me semble que nous jouons ici un triste rôle.","start":22,"end":28,"inf":"jouer","tense":"present","person":3,"work":0,"chapter":90},
  {"id":"eb77fd8516","text":"Je suivrai votre conseil, non parce que vous me le donnez, mais parce que mon intention était de quitter la France.","start":3,"end":10,"inf":"suivre","tense":"futur","person":0,"work":0,"chapter":91},
  {"id":"d6d3d9b872","text":"Un quart d’heure après, il rentrait à l’hôtel de la rue du Helder.","start":27,"end":35,"inf":"rentrer","tense":"imparfait","person":2,"work":0,"chapter":91},
  {"id":"2f43270746","text":"Il faut, pour commencer l’apprentissage de cette rude existence, que j’emprunte à un ami le pain que je mangerai d’ici au moment où j’en gagnerai d’autre.","start":104,"end":112,"inf":"manger","tense":"futur","person":0,"work":0,"chapter":91},
  {"id":"44c83f7813","text":"Quelque carrière que tu suives, tu rendras en peu de temps ce nom illustre.","start":24,"end":30,"inf":"suivre","tense":"subjonctif","person":1,"work":0,"chapter":91},
  {"id":"f9ce9646d8","text":"Et quel est le traitement que vous suivez pour cette maladie inconnue ?","start":35,"end":41,"inf":"suivre","tense":"present","person":4,"work":0,"chapter":93},
  {"id":"b7a1a9806c","text":"On les avait conduites à la chambre de Madame de Villefort, qui avait dit qu’elle recevrait chez elle.","start":82,"end":91,"inf":"recevoir","tense":"conditionnel","person":2,"work":0,"chapter":93},
  {"id":"dc0a12b963","text":"Cette fois, je connaîtrai l’assassin et je frapperai.","start":15,"end":25,"inf":"connaître","tense":"futur","person":0,"work":0,"chapter":94},
  {"id":"37b8064878","text":"Vous espérez, dit-il, que l’assassin se lassera ?","start":5,"end":12,"inf":"espérer","tense":"present","person":4,"work":0,"chapter":94},
  {"id":"6e4ed77596","text":"Alors, pour ne point vous retarder, je monterai, si vous le voulez bien, dans votre calèche, et Tom nous suivra, conduisant mon phaéton à la remorque.","start":39,"end":47,"inf":"monter","tense":"futur","person":0,"work":0,"chapter":96},
  {"id":"727d0fdc3b","text":"nous partirons le soir de la signature du contrat, au lieu de partir le soir des noces.","start":5,"end":14,"inf":"partir","tense":"futur","person":3,"work":0,"chapter":97},
  {"id":"a25a386f22","text":"Nous remonterons le Rhin jusqu’à Strasbourg, nous traverserons la Suisse et nous descendrons en Italie par le Saint-Gothard.","start":81,"end":92,"inf":"descendre","tense":"futur","person":3,"work":0,"chapter":97},
  {"id":"71ebdb9f80","text":"Quelques-uns d’entre eux, les grands noms du bagne, furent salués d’acclamations et d’applaudissements qu’ils recevaient avec une sorte de modestie fière.","start":110,"end":120,"inf":"recevoir","tense":"imparfait","person":5,"work":2,"chapter":null},
  {"id":"1399f2b7ab","text":"Nous partons à sept heures et demie précises pour la Conciergerie.","start":5,"end":12,"inf":"partir","tense":"present","person":3,"work":2,"chapter":null},
  {"id":"4eff2bbe6a","text":"Vous choisissez un singulier vase pour y puiser du bonheur.","start":5,"end":15,"inf":"choisir","tense":"present","person":4,"work":2,"chapter":null},
  {"id":"82b4ebf47b","text":"Vous sentez bien qu’il faut apprendre à lire, à écrire et à compter, pour pouvoir aider votre tante à tenir ses livres de fermage.","start":5,"end":11,"inf":"sentir","tense":"present","person":4,"work":1,"chapter":11},
  {"id":"37381968d2","text":"Après votre leçon, vous travaillez au linge de la maison, ou vous vous brodez un joli bonnet à la paysanne…","start":24,"end":34,"inf":"travailler","tense":"present","person":4,"work":1,"chapter":11},
  {"id":"840709d971","text":"Car nous revenons par la prairie, n’est-ce pas, monsieur Rodolphe ?","start":9,"end":17,"inf":"revenir","tense":"present","person":3,"work":1,"chapter":11},
  {"id":"fab3063c5a","text":"Après cela, vous lisez ou vous travaillez pendant que votre tante fait sa partie de cartes.","start":17,"end":22,"inf":"lire","tense":"present","person":4,"work":1,"chapter":11},
  {"id":"43c0a52b2b","text":"On vivrait cent ans comme cela, monsieur Rodolphe, sans penser à s’ennuyer un moment…","start":3,"end":10,"inf":"vivre","tense":"conditionnel","person":2,"work":1,"chapter":11},
  {"id":"b1e02032af","text":"Vous montez en carriole d’osier avec votre tante et Jacques, le garçon de ferme, pour aller à la grand-messe du village.","start":5,"end":11,"inf":"monter","tense":"present","person":4,"work":1,"chapter":11},
  {"id":"af232b5dc2","text":"Tenez, monseigneur, nous ne nous entendrons pas.","start":33,"end":43,"inf":"entendre","tense":"futur","person":3,"work":1,"chapter":13},
  {"id":"f179d09a14","text":"Tu boiras la honte du fils comme tu as bu la honte du père.","start":3,"end":9,"inf":"boire","tense":"futur","person":1,"work":1,"chapter":14},
  {"id":"dd10b2bdf9","text":"Nous parlerions de nos petites affaires en cassant une croûte.","start":5,"end":15,"inf":"parler","tense":"conditionnel","person":3,"work":1,"chapter":15},
  {"id":"fe8f0e35bb","text":"Dans peu d’instants il ne pourrait plus crier, l’eau avait atteint la hauteur de son cou, bientôt elle arriverait jusqu’à sa bouche.","start":103,"end":113,"inf":"arriver","tense":"conditionnel","person":2,"work":1,"chapter":18},
  {"id":"d6f235f81c","text":"Non, mais il sautera sur vous dès qu’il entendra dire que vous êtes plus fort que lui, répondit le Chourineur en se frottant les mains.","start":40,"end":48,"inf":"entendre","tense":"futur","person":2,"work":1,"chapter":2},
  {"id":"2185759e75","text":"Et alors, abruti par la terreur, ce ne serait plus qu’une masse inerte, insensible, qu’on offrirait en holocauste aux mânes de tes victimes…","start":90,"end":99,"inf":"offrir","tense":"conditionnel","person":2,"work":1,"chapter":21},
  {"id":"a62790ad58","text":"On l’appelait Rigolette, parce qu’elle riait toujours.","start":39,"end":44,"inf":"rire","tense":"imparfait","person":2,"work":1,"chapter":3},
  {"id":"1bb10603c5","text":"Tu mangeras ces deux mufles tout à l’heure, ils ne t’échapperont pas…","start":3,"end":11,"inf":"manger","tense":"futur","person":1,"work":1,"chapter":5},
  {"id":"831e7f98ee","text":"Tiens, la Chouette, je finirai par t’épouser, dit le Maître d’école.","start":23,"end":30,"inf":"finir","tense":"futur","person":0,"work":1,"chapter":6},
  {"id":"0afa3824d4","text":"il vend tout ce qu’il est défendu de vendre, il fait tout ce qu’il est défendu de faire.","start":3,"end":7,"inf":"vendre","tense":"present","person":2,"work":1,"chapter":6},
  {"id":"5016b6db0c","text":"voyez-vous, on mangeait la lune et les étoiles.","start":15,"end":23,"inf":"manger","tense":"imparfait","person":2,"work":1,"chapter":6},
  {"id":"582f1110bb","text":"Au fait j’aime mieux qu’ils aillent du côté des décombres, dit tout bas le Maître d’école.","start":28,"end":35,"inf":"aller","tense":"subjonctif","person":5,"work":1,"chapter":7},
  {"id":"5022dacfac","text":"Le Chourineur se résolut d’avertir Rodolphe du danger qu’il courait.","start":60,"end":67,"inf":"courir","tense":"imparfait","person":2,"work":1,"chapter":7},
  {"id":"7e42c800e4","text":"Mais quand je lui ai dit que je lui permettais de passer la journée à la campagne, j’ai cru qu’elle devenait folle.","start":100,"end":108,"inf":"devenir","tense":"imparfait","person":2,"work":1,"chapter":8},
  {"id":"2cb80fcef1","text":"Arrivé au bout de la rue, je commence à m’apercevoir qu’il tombait par trop de hallebardes…","start":59,"end":66,"inf":"tomber","tense":"imparfait","person":2,"work":1,"chapter":9},
  {"id":"8d62397308","text":"Si l’averse dure longtemps, je dormirai aussi bien là que dans mon garni.","start":31,"end":39,"inf":"dormir","tense":"futur","person":0,"work":1,"chapter":9},
  {"id":"9570af77dc","text":"Nous conduirons le lecteur dans la petite ville de l’Île-Adam, située dans une position ravissante, au bord de la rivière de l’Oise, au pied d’une forêt.","start":5,"end":15,"inf":"conduire","tense":"futur","person":3,"work":1,"chapter":1},
  {"id":"1661b7c1de","text":"Avant de suivre notre héros dans cette nouvelle excursion, nous jetterons un coup d’œil rétrospectif sur Tom et sur Sarah, personnages importants de cette histoire.","start":64,"end":73,"inf":"jeter","tense":"futur","person":3,"work":1,"chapter":11},
  {"id":"d8a14c9862","text":"Sarah partageait l’amour du prince, mais elle préférait la mort au déshonneur et ne pouvait être que la femme de Son Altesse.","start":46,"end":55,"inf":"préférer","tense":"imparfait","person":2,"work":1,"chapter":14},
  {"id":"11d158fcef","text":"S’il lui fallait renoncer à l’amour de Rodolphe, elle prendrait cette douloureuse résolution le plus promptement possible.","start":54,"end":63,"inf":"prendre","tense":"conditionnel","person":2,"work":1,"chapter":14},
  {"id":"dfab821e67","text":"Il préférera tolérer ce qu’il n’aura pu empêcher.","start":3,"end":12,"inf":"préférer","tense":"futur","person":2,"work":1,"chapter":14},
  {"id":"df91641453","text":"Elle perdait l’appui de ses conseils, mais aussi, dans le cas où tout se découvrirait, il serait à l’abri de la colère du grand-duc.","start":5,"end":12,"inf":"perdre","tense":"imparfait","person":2,"work":1,"chapter":14},
  {"id":"8febca21b4","text":"J’écouterai sa bouche mentir pendant que je lirai le crime dans son cœur déjà vicié.","start":44,"end":49,"inf":"lire","tense":"futur","person":0,"work":1,"chapter":19},
  {"id":"13f89c664b","text":"Pourquoi donc qu’elle viendrait te chercher ?","start":22,"end":31,"inf":"venir","tense":"conditionnel","person":2,"work":1,"chapter":20},
  {"id":"2e816e561b","text":"Ne tâche-t-elle pas de compenser par les services qu’elle rend l’hospitalité qu’on lui donne ?","start":58,"end":62,"inf":"rendre","tense":"present","person":2,"work":1,"chapter":22},
  {"id":"2b2a35cc93","text":"Il désire que vous fassiez partir ce matin ces dépêches par un courrier spécial, au lieu d’attendre à lundi.","start":19,"end":26,"inf":"faire","tense":"subjonctif","person":4,"work":1,"chapter":4},
  {"id":"d43f3748ce","text":"Elle travaillait pour vivre, mais l’ouvrage et la santé lui manquaient.","start":5,"end":16,"inf":"travailler","tense":"imparfait","person":2,"work":1,"chapter":6},
  {"id":"4b3323e62d","text":"David, rougissant de s’humilier davantage, parla d’un ton ferme des services qu’il rendait et de son désintéressement.","start":83,"end":90,"inf":"rendre","tense":"imparfait","person":2,"work":1,"chapter":7},
  {"id":"bd5ba7e9b9","text":"Nous retournons à bord de notre brick, mouillé à une très-petite distance.","start":5,"end":15,"inf":"retourner","tense":"present","person":3,"work":1,"chapter":7},
  {"id":"8c1a255562","text":"Mais je n’apporterai que deux verres, moi et Alfred nous buvons toujours dans le même.","start":57,"end":63,"inf":"boire","tense":"present","person":3,"work":1,"chapter":8},
  {"id":"6e5ffa0616","text":"Elle lit dans votre main comme dans un livre.","start":5,"end":8,"inf":"lire","tense":"present","person":2,"work":1,"chapter":9},
  {"id":"6f0f4f91d3","text":"Mais, si on ne faisait que ce qui est permis, dites donc, on resterait joliment souvent les bras croisés.","start":61,"end":70,"inf":"rester","tense":"conditionnel","person":2,"work":1,"chapter":9},
  {"id":"a2cd14fa40","text":"Elle reconduit comme ça tous les jours le sanglier à sa cassine, et elle revient toute seule.","start":73,"end":80,"inf":"revenir","tense":"present","person":2,"work":1,"chapter":1},
  {"id":"4f12d2a1fd","text":"Je veux que tu doives tout à ta Chouette chérie.","start":15,"end":21,"inf":"devoir","tense":"subjonctif","person":1,"work":1,"chapter":1},
  {"id":"b4ba24a731","text":"elle choisirait en raison de l’élévation de son âme…","start":5,"end":15,"inf":"choisir","tense":"conditionnel","person":2,"work":1,"chapter":13},
  {"id":"41d9ac1875","text":"Recevant de Rodolphe l’avis du danger qu’elle courait, Clémence avait monté précipitamment au cinquième.","start":46,"end":53,"inf":"courir","tense":"imparfait","person":2,"work":1,"chapter":15},
  {"id":"64d9b6f59b","text":"Je n’ai pas besoin de vous demander s’il vivait dans le même isolement ?","start":41,"end":47,"inf":"vivre","tense":"imparfait","person":2,"work":1,"chapter":16},
  {"id":"862056cb31","text":"N’avais-je pas raison de vous écrire que, si vous vouliez bien venir ici ce soir, vous finiriez la journée comme vous l’avez commencée…","start":87,"end":95,"inf":"finir","tense":"conditionnel","person":4,"work":1,"chapter":17},
  {"id":"f0a7532156","text":"Nous conduirons le lecteur dans ce triste logis.","start":5,"end":15,"inf":"conduire","tense":"futur","person":3,"work":1,"chapter":18},
  {"id":"a16ef6d5e2","text":"Et alors qu’est-ce que vous deviendriez tous ?","start":28,"end":39,"inf":"devenir","tense":"conditionnel","person":4,"work":1,"chapter":19},
  {"id":"f962044a03","text":"Nous demanderons à passer la nuit à la ferme, dans un coin de l’étable.","start":5,"end":16,"inf":"demander","tense":"futur","person":3,"work":1,"chapter":3},
  {"id":"6f2c550056","text":"Si on ne me croit pas, je montrerai la plaie que j’ai gardée depuis que j’ai brisé ma manille, et dont je souffre toujours.","start":26,"end":35,"inf":"montrer","tense":"futur","person":0,"work":1,"chapter":3},
  {"id":"2e514d37f9","text":"On les payait largement, on rendait leur sort très-heureux, très-enviable.","start":28,"end":35,"inf":"rendre","tense":"imparfait","person":2,"work":1,"chapter":4},
  {"id":"df4366497f","text":"À présent, elle court comme un Basque, et elle se promet, au premier jour, d’aller à pied remercier son sauveur, allée des Veuves, à Paris…","start":16,"end":21,"inf":"courir","tense":"present","person":2,"work":1,"chapter":5},
  {"id":"e4b8f16a0e","text":"Notre vénérable curé l’instruirait avec les autres enfants du village, et il grandirait dans le bien, comme on dit.","start":77,"end":87,"inf":"grandir","tense":"conditionnel","person":2,"work":1,"chapter":6},
  {"id":"956a3b1025","text":"On resterait deux ans à la ferme, pour faire ensuite place à d’autres laboureurs choisis aux mêmes conditions.","start":3,"end":12,"inf":"rester","tense":"conditionnel","person":2,"work":1,"chapter":6},
  {"id":"87a3b49cb8","text":"Quant à toi, mon enfant, tu dormiras bien, c’est de ton âge.","start":28,"end":36,"inf":"dormir","tense":"futur","person":1,"work":1,"chapter":7},
  {"id":"f37a506a1e","text":"En agissant ainsi, ce ne sont pas des fonctions que vous remplissez…","start":57,"end":67,"inf":"remplir","tense":"present","person":4,"work":1,"chapter":12},
  {"id":"ed291a269c","text":"Il mettait enfin sa joie dans la probité, son orgueil dans l’honneur, sa félicité dans la religion.","start":3,"end":10,"inf":"mettre","tense":"imparfait","person":2,"work":1,"chapter":13},
  {"id":"420715debf","text":"Il pensera, j’en suis sûr, absolument comme moi.","start":3,"end":10,"inf":"penser","tense":"futur","person":2,"work":1,"chapter":15},
  {"id":"f40f584a7a","text":"Vous écrirez donc à Monsieur d’Orbigny, il attend votre lettre afin de vous adresser ses pleins pouvoirs…","start":5,"end":12,"inf":"écrire","tense":"futur","person":4,"work":1,"chapter":16},
  {"id":"a894e448f1","text":"Je vous laisse donc, mon cher monsieur Ferrand, dit Madame d’Orbigny, vous écrirez à mon mari…","start":75,"end":82,"inf":"écrire","tense":"futur","person":4,"work":1,"chapter":16},
  {"id":"dc35f2c55f","text":"Je sais que vous préférez souvent la solitude lorsque vous n’allez pas dans le monde…","start":17,"end":25,"inf":"préférer","tense":"present","person":4,"work":1,"chapter":20},
  {"id":"58b6294dba","text":"Vous devrez à l’amitié dévouée des soins que l’amour ne pourrait vous donner…","start":5,"end":11,"inf":"devoir","tense":"futur","person":4,"work":1,"chapter":20},
  {"id":"7cc5da4118","text":"Il s’occupait alors de ressemeler une botte, avec le sérieux de la conscience qu’il mettait à toutes choses.","start":84,"end":91,"inf":"mettre","tense":"imparfait","person":2,"work":1,"chapter":3},
  {"id":"57a0d2c249","text":"Dès qu’elle rentrera, je lui ferai garder la loge et je m’occuperai de vos commissions.","start":12,"end":20,"inf":"rentrer","tense":"futur","person":2,"work":1,"chapter":3},
  {"id":"534ee94a3c","text":"Après ça vous me direz sans doute qu’on vend au Temple des souliers d’enfants…","start":40,"end":44,"inf":"vendre","tense":"present","person":2,"work":1,"chapter":4},
  {"id":"86838937a2","text":"Quelquefois, par méchanceté, elle souillait devant moi les restes du repas qu’on me laissait, car presque toujours elle mangeait avec monsieur Ferrand.","start":120,"end":128,"inf":"manger","tense":"imparfait","person":2,"work":1,"chapter":9},
  {"id":"c439c8f408","text":"Vous méritez tant d’intérêt que je réussirai, j’en suis sûre.","start":35,"end":44,"inf":"réussir","tense":"futur","person":0,"work":1,"chapter":10},
  {"id":"8f4d6e9211","text":"Et vous ne savez pas quand il rentrera, monsieur Bradamanti ?","start":30,"end":38,"inf":"rentrer","tense":"futur","person":2,"work":1,"chapter":12},
  {"id":"e8195fd273","text":"J’étais bien sûre que vous penseriez comme moi, reprit Madame Pipelet.","start":27,"end":36,"inf":"penser","tense":"conditionnel","person":4,"work":1,"chapter":12},
  {"id":"76fa9d8ee7","text":"Car il m’a bien recommandé de lui cacher qu’il partait ce soir à six heures.","start":47,"end":54,"inf":"partir","tense":"imparfait","person":2,"work":1,"chapter":12},
  {"id":"c9a696213b","text":"Mais elle devra ne rien cacher à un avocat qui viendra de ma part s’entendre avec elle pour sa défense.","start":10,"end":15,"inf":"devoir","tense":"futur","person":2,"work":1,"chapter":14},
  {"id":"0974fe0430","text":"pour me trouver à mon aise, je travaillerai une heure de plus par jour, je me coucherai à minuit au lieu de me coucher à onze heures.","start":31,"end":43,"inf":"travailler","tense":"futur","person":0,"work":1,"chapter":14},
  {"id":"5df8f28ea3","text":"J’ai vu avec quel courage admirable vous travaillez, et combien il vous fallait d’ordre, de sagesse, pour vivre du modique salaire que vous gagnez si péniblement.","start":41,"end":51,"inf":"travailler","tense":"present","person":4,"work":1,"chapter":15},
  {"id":"0f77011303","text":"Et alors on regardera comme le fait d’une hérédité inexorablement fatale une corruption causée par l’égoïste incurie de la société…","start":12,"end":21,"inf":"regarder","tense":"futur","person":2,"work":1,"chapter":16},
  {"id":"3c5bfdaabb","text":"Tour à tour colère ou suppliante, elle grondait, elle implorait, mais on riait encore plus de ses plaintes que de ses menaces.","start":73,"end":78,"inf":"rire","tense":"imparfait","person":2,"work":1,"chapter":7},
  {"id":"9016f8985e","text":"si on la laissait faire, elle finirait par nous manger la laine sur le dos.","start":30,"end":38,"inf":"finir","tense":"conditionnel","person":2,"work":1,"chapter":7},
  {"id":"7b1a13dafc","text":"Car si votre misérable vie d’à présent vous paraît un enfer, vous préférerez celle dont je vous ai parlé.","start":66,"end":76,"inf":"préférer","tense":"futur","person":4,"work":1,"chapter":9},
  {"id":"60149d94fa","text":"Et elle examina les traits des enfants pour voir s’ils comprendraient la méchante portée de ces paroles.","start":55,"end":69,"inf":"comprendre","tense":"conditionnel","person":5,"work":1,"chapter":1},
  {"id":"ba47d7ae5d","text":"Il faudra même que la promenade se fasse après le soleil couché, afin que la nuit soit noire lorsqu’elles tomberont à l’eau.","start":106,"end":115,"inf":"tomber","tense":"futur","person":5,"work":1,"chapter":1},
  {"id":"5a4421ffc1","text":"Je n’avais pourtant jamais pensé que d’un moment à l’autre vous partiriez d’ici…","start":64,"end":73,"inf":"partir","tense":"conditionnel","person":4,"work":1,"chapter":10},
  {"id":"cd1a5d046a","text":"Et qui gardera votre enfant pendant que vous travaillerez ?","start":45,"end":57,"inf":"travailler","tense":"futur","person":4,"work":1,"chapter":10},
  {"id":"ca830d2c02","text":"et qu’elle conduisait alors à une mort certaine.","start":11,"end":21,"inf":"conduire","tense":"imparfait","person":2,"work":1,"chapter":11},
  {"id":"3c3970e7b6","text":"Seulement, ce qui m’étonne, c’est que tu croies qu’il est commis voyageur.","start":41,"end":47,"inf":"croire","tense":"subjonctif","person":1,"work":1,"chapter":11},
  {"id":"6ab2d8c8a9","text":"On rafle la famille, et les enfants seront sur le pavé, où ils apprendront l’état de ton père et de ton grand-père aussi bien qu’ici.","start":63,"end":74,"inf":"apprendre","tense":"futur","person":5,"work":1,"chapter":2},
  {"id":"77cc6514d4","text":"Si nos têtes tombent, elles tomberont dans le même panier…","start":28,"end":37,"inf":"tomber","tense":"futur","person":5,"work":1,"chapter":2},
  {"id":"f1c2401474","text":"Mais, comme je n’ai pas de quoi me loger ailleurs, moi et les enfants, nous habiterons la baraque au bout de l’île.","start":76,"end":86,"inf":"habiter","tense":"futur","person":3,"work":1,"chapter":2},
  {"id":"fcb0d4ff50","text":"ça lui était bien égal, parce qu’il retournerait rejoindre les bons enfants de la geôle, comme il dit.","start":36,"end":48,"inf":"retourner","tense":"conditionnel","person":2,"work":1,"chapter":3},
  {"id":"5b454a6cd7","text":"Demain matin, dit celui-ci, je rendrai les foulards à Nicolas.","start":31,"end":38,"inf":"rendre","tense":"futur","person":0,"work":1,"chapter":3},
  {"id":"4cbd0cc197","text":"On nous bat parce que nous écoutons plutôt Martial que les autres…","start":27,"end":35,"inf":"écouter","tense":"present","person":3,"work":1,"chapter":3},
  {"id":"16c3571657","text":"Pour lui tout seul, il ne serait pas gêné, il retournerait être braconnier dans les bois qu’il aime tant.","start":46,"end":58,"inf":"retourner","tense":"conditionnel","person":2,"work":1,"chapter":3},
  {"id":"2677dfa748","text":"Et puis l’on saurait par lui peut-être si Monsieur de Saint-Remy, son père, n’aurait pas quitté Angers avant que vous ne lui ayez écrit.","start":13,"end":20,"inf":"savoir","tense":"conditionnel","person":2,"work":1,"chapter":5},
  {"id":"7f1ce40e62","text":"Faute d’une expression plus particulière, nous appellerions ces gens-là des hommes-courtisanes, si cela se pouvait dire.","start":47,"end":59,"inf":"appeler","tense":"conditionnel","person":3,"work":1,"chapter":6},
  {"id":"f3f6dd76be","text":"Car notre maison nous faisait honneur, et jusqu’au dernier moment je servirai Monsieur le vicomte avec le respect et l’estime qui lui sont dus.","start":69,"end":77,"inf":"servir","tense":"futur","person":0,"work":1,"chapter":6},
  {"id":"b9e5da72d8","text":"Il n’y a rien que de sérieux, que de triste dans tout ceci, et vous riez !","start":68,"end":72,"inf":"rire","tense":"present","person":4,"work":1,"chapter":7},
  {"id":"01266a75f5","text":"pareil à celui qui vous accueille quand vous entrez quelque part, puis les regards des femmes surtout se fixèrent sur un très beau garçon…","start":45,"end":51,"inf":"entrer","tense":"present","person":4,"work":1,"chapter":8},
  {"id":"79f25071bf","text":"Mais c’est que c’est vrai, reprit le duc, on donnerait vingt indifférents pour un ami…","start":45,"end":54,"inf":"donner","tense":"conditionnel","person":2,"work":1,"chapter":9},
  {"id":"fbee602c81","text":"Un jour viendrait où vous préféreriez l’impunité de vos nouveaux crimes à la vie d’autrui.","start":26,"end":37,"inf":"préférer","tense":"conditionnel","person":4,"work":1,"chapter":9},
  {"id":"559419cf6d","text":"Est-il vrai qu’il y a trois jours madame a été vous chercher rue du Temple, numéro dix-sept, où vous habitez, caché sous le faux nom de Bradamanti ?","start":101,"end":108,"inf":"habiter","tense":"present","person":4,"work":1,"chapter":11},
  {"id":"d38def31b7","text":"Ainsi l’on apprendra nécessairement quelque chose.","start":11,"end":20,"inf":"apprendre","tense":"futur","person":2,"work":1,"chapter":11},
  {"id":"a0a79a6d66","text":"Pendant que je parlerais, vous joueriez des dents…","start":31,"end":39,"inf":"jouer","tense":"conditionnel","person":4,"work":1,"chapter":12},
  {"id":"6d131ea747","text":"Au milieu de ces tortures sans nom, il perdait la santé, l’appétit, le sommeil.","start":39,"end":46,"inf":"perdre","tense":"imparfait","person":2,"work":1,"chapter":13},
  {"id":"80af0c1eb2","text":"Chaque jour vous promettez de nous aider à mettre la main sur la bande…","start":17,"end":26,"inf":"promettre","tense":"present","person":4,"work":1,"chapter":5},
  {"id":"2796f90d7d","text":"Je suis sûr que vous mangez à deux râteliers, comme on dit.","start":21,"end":27,"inf":"manger","tense":"present","person":4,"work":1,"chapter":5},
  {"id":"c3c2487f13","text":"Il ne s’agit pas de ce que vous aimeriez mieux, mademoiselle, mais de ce qui est convenable et décent.","start":32,"end":40,"inf":"aimer","tense":"conditionnel","person":4,"work":1,"chapter":8},
  {"id":"4d2a00c15d","text":"Si vous y consentez, amenez-moi votre nièce demain soir à la même heure, et elle entrera tout de suite à mon service…","start":81,"end":88,"inf":"entrer","tense":"futur","person":2,"work":1,"chapter":8},
  {"id":"564655efce","text":"Au bout de deux années, on vendra sans frais les effets qui n’auront pas été dégagés.","start":27,"end":33,"inf":"vendre","tense":"futur","person":2,"work":1,"chapter":14},
  {"id":"8edaae2180","text":"Puisque vous écrivez, mon cher camarade, ayez donc aussi la bonté de noter de demander chez moi mon édredon.","start":13,"end":20,"inf":"écrire","tense":"present","person":4,"work":1,"chapter":3},
  {"id":"332018449a","text":"Malheureusement, au moment où nous ouvrons la bouche pour avaler le morceau, pincés par la rousse.","start":35,"end":42,"inf":"ouvrir","tense":"present","person":3,"work":1,"chapter":7},
  {"id":"17f0806fb7","text":"Faut dire aussi que sur son gain il achetait des cœurs de mouton à Gargousse, car son grand singe mangeait de la viande crue comme un vorace.","start":36,"end":44,"inf":"acheter","tense":"imparfait","person":2,"work":1,"chapter":9},
  {"id":"230ec35fe2","text":"nous montrerons que des femmes ont plus de cœur que ces hommes…","start":5,"end":15,"inf":"montrer","tense":"futur","person":3,"work":1,"chapter":1},
  {"id":"64fe0cd001","text":"Autrefois il lui aurait fallu huit pages pour contenir ce qu’elle écrit maintenant en deux.","start":66,"end":71,"inf":"écrire","tense":"present","person":2,"work":1,"chapter":4},
  {"id":"e56d27b30c","text":"Et il sentira enfin, reprit Clémence en serrant Fleur-de-Marie dans ses bras, que lorsque je vous appelle ma fille…","start":6,"end":13,"inf":"sentir","tense":"futur","person":2,"work":1,"chapter":6},
  {"id":"08a8f06d66","text":"Ce n’est pas une AUMÔNE que nous demandons pour elles, c’est un DROIT RECONNU.","start":33,"end":42,"inf":"demander","tense":"present","person":3,"work":1,"chapter":8},
  {"id":"170debede2","text":"Il nous a dit qu’il retournait en Allemagne sous peu de jours, peut-être qu’il est déjà parti.","start":20,"end":30,"inf":"retourner","tense":"imparfait","person":2,"work":1,"chapter":14},
  {"id":"12599a7610","text":"il ne palpitera que le jour où je sentirai poser sur mon front la couronne souveraine.","start":34,"end":42,"inf":"sentir","tense":"futur","person":0,"work":1,"chapter":2},
  {"id":"be45d7cae1","text":"Lorsque vous le saurez, vous ne pourrez comprendre la lenteur que je mets à vous en instruire car vous regarderez cette révélation comme un miracle du ciel.","start":103,"end":113,"inf":"regarder","tense":"futur","person":4,"work":1,"chapter":2},
  {"id":"b221369f94","text":"Tu m’empêches d’aller retrouver Cecily, mon intérêt veut que tu meures…","start":64,"end":70,"inf":"mourir","tense":"subjonctif","person":1,"work":1,"chapter":5},
  {"id":"fdbb26180c","text":"En lisant les lignes suivantes, on comprendra pourquoi nous les avons fait précéder de quelques réflexions.","start":35,"end":45,"inf":"comprendre","tense":"futur","person":2,"work":1,"chapter":6},
  {"id":"f56d6eba0f","text":"Ici nous commençons sur le vivant des expériences et des études que nous finissons à l’amphithéâtre sur le cadavre.","start":9,"end":19,"inf":"commencer","tense":"present","person":3,"work":1,"chapter":7},
  {"id":"c686c54613","text":"Je veux qu’elle voie au moins une figure amie lorsqu’elle ouvrira les yeux…","start":58,"end":65,"inf":"ouvrir","tense":"futur","person":2,"work":1,"chapter":9},
];
